function buildFieldRunbookContext(proof = currentLaunchProof(), config = currentLaunchConfig()) {
  config = proofConfigForFingerprint(proof, config);
  const audit = buildV2ReportParityAudit(proof, config);
  const retirementGate = buildClassicRetirementGate(proof, audit, config);
  const fieldVerification = buildV2FieldVerification({
    proof,
    config,
    audit,
    retirementGate,
  });
  const requirementsById = new Map((Array.isArray(fieldVerification.requirements) ? fieldVerification.requirements : [])
    .filter((item) => item?.id)
    .map((item) => [item.id, item]));
  const criteriaById = new Map((Array.isArray(fieldVerification.replacementCriteria) ? fieldVerification.replacementCriteria : [])
    .filter((item) => item?.id)
    .map((item) => [item.id, item]));
  return {
    audit,
    retirementGate,
    fieldVerification,
    requirementsById,
    criteriaById,
  };
}

function fieldRunbookStageChecks(stage = {}, context = buildFieldRunbookContext()) {
  const requirementChecks = (Array.isArray(stage.requirements) ? stage.requirements : [])
    .map((id) => context.requirementsById.get(id) || {
      id,
      label: id,
      pass: false,
      action: 'review-field-proof',
      detail: 'Field proof row is not available yet.',
    });
  const criterionChecks = (Array.isArray(stage.criteria) ? stage.criteria : [])
    .map((id) => context.criteriaById.get(id) || {
      id,
      label: id,
      pass: false,
      action: 'review-replacement-criterion',
      detail: 'Replacement-criteria row is not available yet.',
    });
  return [...requirementChecks, ...criterionChecks];
}

function buildFieldRunbookStages(context = buildFieldRunbookContext()) {
  const rows = launchStages.map((stage, index) => {
    const checks = fieldRunbookStageChecks(stage, context);
    const blockers = checks.filter((item) => item.pass !== true);
    const pass = checks.length > 0 && blockers.length === 0;
    const evidenceCount = checks.filter((item) => item.pass === true).length;
    const firstBlocker = blockers[0] || null;
    return {
      ...stage,
      index,
      pass,
      evidenceCount,
      checkCount: checks.length,
      blockers,
      firstBlocker,
      action: firstBlocker?.action || 'none',
      detail: firstBlocker?.detail || stage.detail,
    };
  });
  const firstBlockedIndex = rows.findIndex((stage) => !stage.pass);
  rows.forEach((stage) => {
    if (stage.pass) {
      stage.state = 'done';
      stage.stateClass = 'is-done';
      stage.badge = 'Proof';
      stage.detail = stage.detail || 'Field proof is attached.';
      return;
    }
    if (stage.index === firstBlockedIndex) {
      stage.state = 'active';
      stage.stateClass = stage.evidenceCount > 0 ? 'is-active is-warn' : 'is-active';
      stage.badge = stage.evidenceCount > 0 ? 'Review' : 'Active';
      return;
    }
    stage.state = 'queued';
    stage.stateClass = 'is-queued';
    stage.badge = 'Queued';
  });
  return rows;
}

function renderFieldRunbookSummary(context, rows) {
  const fieldVerification = context.fieldVerification || {};
  if (fieldVerification.ready) return 'Field parity ready';
  const criteriaBlockers = Number(fieldVerification.criteriaBlockerCount || 0);
  const blockerCount = Number(fieldVerification.blockerCount || 0) + criteriaBlockers;
  const nextAction = fieldVerification.nextAction || rows.find((stage) => !stage.pass)?.action || 'review-field-proof';
  return `${blockerCount} blocker${blockerCount === 1 ? '' : 's'} · ${nextAction}`;
}

function fieldRunbookActionControl(action = '', stage = {}) {
  const detail = stage.detail || stage.firstBlocker?.detail || 'Review the current field-verification blocker.';
  const fallback = (label, message = detail) => ({
    dataAction: 'inspect-runbook-blocker',
    label,
    message,
    disabled: false,
  });
  const walletPublicKey = selectedLaunchWalletPublicKey();
  const selectedWallet = selectedManagedWallet();
  const walletLocked = state.secretPin.locked === true || selectedWallet?.secretPinLocked === true;

  if (!action || action === 'none') return null;
  if (action === 'run-demo-launch') {
    return { dataAction: 'run-demo-launch', label: 'Run test launch', disabled: state.demoLaunchRunning === true };
  }
  if (action === 'generate-or-unlock-wallet') {
    if (walletPublicKey && walletLocked) return { dataAction: 'unlock-secret-pin', label: 'Unlock PIN' };
    return { dataAction: walletPublicKey ? 'import-wallet' : 'generate-wallet', label: walletPublicKey ? 'Import wallet' : 'Generate wallet' };
  }
  if (action === 'grind-or-select-vanity-ca') {
    return { dataAction: 'start-vanity', label: state.vanityRunning ? 'Cancel grind' : 'Grind CA', disabled: false };
  }
  if (['stage-launch-plan', 'fix-pool-topology'].includes(action)) {
    return { dataAction: 'review-plan', label: 'Stage plan' };
  }
  if (action === 'run-viewport-smoke') {
    return fallback('Smoke test', 'Run `npm run test:v2:viewport`, then reconnect the desktop app so Trebuchet can verify the proof hash.');
  }
  if (['run-funding-and-quote-checks', 'back-held-reserve'].includes(action)) {
    const fundingEstimateStatus = classicFundingEstimateStatus(currentLaunchConfig());
    if (!fundingEstimateStatus.matchesConfig) {
      return { dataAction: 'estimate-funding', label: fundingEstimateStatus.stale ? 'Re-estimate' : 'Estimate' };
    }
    const quoteStatus = quoteAcquireStatus(currentLaunchConfig());
    if (quoteAcquireRoutes().length && !quoteStatus.ready) {
      return { dataAction: state.quoteAcquire.running ? 'poll-quote-acquire' : 'start-quote-acquire', label: state.quoteAcquire.running ? 'Refresh quote' : 'Acquire quote' };
    }
    if (quoteManualPrefundItems().length) {
      return { dataAction: 'refresh-manual-prefund', label: 'Check prefund', disabled: state.manualPrefund.polling === true };
    }
    return { dataAction: 'check-readiness', label: 'Check' };
  }
  if (action === 'run-non-demo-v2-launch') {
    const canRunFull = state.apiStatus === 'connected'
      && !state.demoActive
      && state.executionReadiness?.status === 'ready'
      && state.executionReadiness?.nextEndpoint
      && !state.fullRunRunning
      && !state.realExecutionRunning;
    return canRunFull
      ? { dataAction: 'run-full-launch', label: 'Run live' }
      : { dataAction: 'check-readiness', label: state.executionChecking ? 'Checking' : 'Check', disabled: state.executionChecking === true };
  }
  if (['attach-terminal-report', 'publish-report-and-sweep'].includes(action)) {
    const proof = currentLaunchProof();
    const config = proofConfigForFingerprint(proof, currentLaunchConfig());
    const reportPublishEvidence = proofHasReportPublishEvidence(proof, config);
    const airdropStatus = airdropCompletionStatus(proof, config.poolTopology);
    const reportProofReady = reportPublishEvidence && airdropStatus.complete;
    if (proof?.canPublishReport && reportProofReady) return { dataAction: 'publish-v2-report', label: state.reportPublishing ? 'Publishing' : 'Publish', disabled: state.reportPublishing === true };
    return {
      dataAction: 'download-v2-dossier',
      label: 'Dossier',
      disabled: !airdropStatus.complete || !proofCanCreateLocalDossier(proof, config),
    };
  }
  if (action === 'load-or-resume-journal') {
    return { dataAction: 'inspect-recovery', label: 'Open coin' };
  }
  if (action === 'resolve-proof-audit') {
    return fallback('Audit', 'Open Diagnostics and resolve the missing proof-audit rows before retiring Classic.');
  }
  if (action === 'complete-replacement-criteria') {
    return fallback('Criteria', 'Complete every replacement-criteria chip before retiring Classic.');
  }
  return fallback('Review');
}

function renderStages() {
  const context = buildFieldRunbookContext();
  const rows = buildFieldRunbookStages(context);
  $('#runbookSummary').textContent = renderFieldRunbookSummary(context, rows);
  $('#stageList').innerHTML = rows.map((stage, index) => {
    const done = stage.pass;
    const active = !done && stage.state === 'active';
    const queued = !done && !active;
    const badgeClass = done ? '' : active && stage.evidenceCount > 0 ? 'warn' : active ? 'danger' : 'warn';
    const actionLine = done
      ? `${stage.evidenceCount}/${stage.checkCount} proof checks attached.`
      : active
        ? `Next: ${stage.action || 'review-field-proof'}`
        : `Waiting on ${stage.firstBlocker?.label || 'prior field proof'}.`;
    const control = active ? fieldRunbookActionControl(stage.action, stage) : null;
    const controlAttrs = control
      ? [
        `data-action="${escapeHtml(control.dataAction)}"`,
        control.message ? `data-message="${escapeHtml(control.message)}"` : '',
        control.disabled ? 'disabled' : '',
      ].filter(Boolean).join(' ')
      : '';
    return `
      <article class="stage-row ${stage.stateClass || ''}">
        <span class="stage-num">${done ? '<i class="fa-solid fa-check"></i>' : index + 1}</span>
        <span class="stage-copy">
          <h3>${escapeHtml(stage.title)}</h3>
          <p>${escapeHtml(stage.detail)}</p>
          <small class="stage-action">${escapeHtml(actionLine)}</small>
        </span>
        <span class="stage-status-stack">
          <span class="tx-state ${badgeClass}">${done ? 'Done' : active ? stage.badge : queued ? 'Queued' : stage.badge}</span>
          ${control ? `<button class="pill-button stage-control" type="button" ${controlAttrs}>${escapeHtml(control.label)}</button>` : ''}
        </span>
      </article>
    `;
  }).join('');
}

function renderQueue() {
  const context = runProgressContext();
  const { rows, total, signed, pending, percent, activeId, isLive } = context;
  const activeTx = rows.find((tx) => tx.id === activeId) || rows[0] || null;
  const pendingRows = state.transactions.length
    ? rows.filter((tx) => tx.state === 'pending')
    : isLive
      ? activeTx ? [activeTx] : []
      : rows.slice(0, 4);
  const planSource = state.launchPlan?.source === 'local-api' ? 'local API' : 'static';
  const queueTitle = state.transactions.length
    ? `${signed} / ${total} complete`
    : isLive
      ? activeTx?.state === 'blocked' ? 'Resolve blocker' : activeTx?.label || context.headingLabel
      : 'Review run plan';
  $('#queueTitle').textContent = queueTitle;
  $('#queueList').innerHTML = state.transactions.length
    ? `
      <div class="queue-progress">
        <span style="width:${percent}%"></span>
      </div>
      ${pendingRows.length ? pendingRows.slice(0, 1).map((tx) => `
        <article class="queue-row compact">
          <span class="queue-copy">
            <h3>Run envelope armed</h3>
            <p>Trebuchet will sign ${pending} queued operation${pending === 1 ? '' : 's'} from ${escapeHtml(account().name)}.</p>
          </span>
          <button class="secondary-button compact" type="button" data-action="review" data-tx="${escapeHtml(tx.id)}">
            <i class="fa-solid fa-shield-halved"></i>
            <span>Envelope</span>
          </button>
        </article>
      `).join('') : '<div class="empty-state">Run complete.</div>'}
      <div class="kv-row"><span>Plan source</span><strong>${escapeHtml(planSource)}</strong></div>
      <div class="next-hint">One armed run replaces per-transaction wallet prompts.</div>
    `
    : isLive ? `
      <div class="queue-progress">
        <span style="width:${percent}%"></span>
      </div>
      <div class="queue-row compact ${escapeHtml(activeTx?.state || '')}">
        <span class="queue-copy">
          <h3>${escapeHtml(activeTx?.state === 'blocked' ? 'Live checkpoint blocked' : context.focusLabel)}</h3>
          <p>${escapeHtml(activeTx?.effects?.[0] || 'Trebuchet is watching launch record and readiness evidence.')}${pinUnlockButton(activeTx?.effects?.[0])}</p>
        </span>
      </div>
      <div class="kv-row"><span>Source</span><strong>${escapeHtml(context.source)}</strong></div>
      <div class="kv-row"><span>Progress</span><strong>${signed}/${total}</strong></div>
      <div class="kv-row"><span>Next</span><strong>${escapeHtml(activeTx?.label || 'Review proof')}</strong></div>
      <div class="next-hint">Live evidence replaces repeated wallet prompts once Trebuchet controls the launch key.</div>
    `
    : `
      <div class="queue-progress">
        <span style="width:0%"></span>
      </div>
      <div class="queue-row compact">
        <span class="queue-copy">
          <h3>Fund first, run later</h3>
          <p>Trebuchet stages one decoded run envelope for its local launch wallet.</p>
        </span>
      </div>
      <div class="kv-row"><span>Mode</span><strong>${escapeHtml(state.launchMode)}</strong></div>
      <div class="kv-row"><span>Blockers</span><strong>${bootGuardrails().filter((item) => item.state === 'danger').length}</strong></div>
      <div class="kv-row"><span>Runtime</span><strong>${escapeHtml(state.apiStatus === 'connected' ? 'Local app' : 'Preview')}</strong></div>
    `;

  const stageButton = $('#stageButton');
  stageButton.disabled = state.staging;
  stageButton.querySelector('span').textContent = state.staging
    ? 'Reviewing'
    : state.transactions.length ? 'Review again' : 'Review run plan';
  if (pending === 0 && (state.transactions.length > 0 || isLive)) {
    $('#queueTitle').textContent = 'Complete';
  }
}

function bootGuardrails() {
  const apiState = state.apiStatus === 'connected' ? 'pass' : 'warn';
  const rpcState = state.apiStatus === 'connected' && state.rpcHealth !== 'error' ? 'pass' : 'warn';
  const recoveryState = state.recovery.failedJournalCount > 0 || state.recovery.pendingWalletCount > 0
    ? 'warn'
    : 'pass';
  const recoveryDetail = state.apiStatus === 'connected'
    ? `${state.recovery.journalCount} launch journals, ${state.recovery.pendingWalletCount} pending wallets.`
    : 'Recovery inventory is available after the desktop app connects.';
  const planGuardrails = Array.isArray(state.launchPlan?.guardrails)
    ? state.launchPlan.guardrails.map((item) => ({
      id: item.id,
      title: item.title,
      detail: item.detail,
      state: item.state || 'pass',
    }))
    : [];

  return [
    {
      id: 'api',
      title: state.apiStatus === 'connected' ? 'Local API connected' : 'Static preview',
      detail: state.apiDetail,
      state: apiState,
    },
    {
      id: 'rpc',
      title: 'RPC health',
      detail: state.apiStatus === 'connected'
        ? `${state.rpcName}: ${state.rpcHealthLabel}`
        : 'RPC health requires the desktop app.',
      state: rpcState,
    },
    ...planGuardrails,
    ...guardrails.filter((item) => item.id !== 'rpc' && item.id !== 'resume'),
    {
      id: 'resume',
      title: 'Recovery inventory',
      detail: recoveryDetail,
      state: recoveryState,
    },
  ];
}

function renderGuardrails() {
  const items = bootGuardrails();
  const warnings = items.filter((item) => item.state !== 'pass');
  const passes = items.filter((item) => item.state === 'pass');
  const visible = [...warnings, ...passes].slice(0, 4);
  const omitted = Math.max(0, items.length - visible.length);
  $('#preflightSummary').textContent = warnings.length
    ? `${warnings.length} warning${warnings.length === 1 ? '' : 's'}`
    : 'Clear';
  $('#guardrailList').innerHTML = [
    ...visible.map((item) => {
    const icon = item.state === 'pass' ? 'fa-check' : item.state === 'warn' ? 'fa-triangle-exclamation' : 'fa-ban';
    const label = item.state === 'pass' ? 'Pass' : item.state === 'warn' ? 'Warn' : 'Blocked';
    return `
      <article class="guardrail-row ${item.state}">
        <span>
          <h3><i class="fa-solid ${icon}"></i> ${escapeHtml(item.title)}</h3>
          <p>${escapeHtml(item.detail)}</p>
        </span>
        <span class="risk-badge ${item.state === 'warn' ? 'warn' : item.state === 'danger' ? 'danger' : ''}">${label}</span>
      </article>
    `;
    }),
    omitted
      ? `<article class="guardrail-row muted-row"><span><h3>${omitted} checks quiet</h3><p>Passing checks are collapsed.</p></span></article>`
      : '',
  ].join('');
}

function demoRunHasCompletedReadiness(run = state.lastDemoLaunchRun) {
  if (!run || typeof run !== 'object') return false;
  const tokenMint = String(run.token?.tokenMint || run.token?.mint || '').trim();
  const results = Array.isArray(run.liquidity?.results) ? run.liquidity.results : [];
  const resultCount = Number(results.length);
  const readiness = run.readiness || {};
  const completion = readiness.completion || {};
  const sweepPhase = Array.isArray(readiness.phases)
    ? readiness.phases.find((phase) => phase.id === 'sweep')
    : null;
  const config = demoRunLaunchConfig(run);
  const topology = config?.poolTopology || {};
  const plannedAirdropRows = Array.isArray(topology?.airdrop?.recipients)
    ? topology.airdrop.recipients
    : [];
  const plannedAirdropCount = topology?.airdrop?.enabled
    ? Math.max(
      Math.max(0, Math.floor(Number(topology.airdrop.recipientCount || 0))),
      plannedAirdropRows.length,
    )
    : 0;
  const airdrop = run.transfer?.airdrop || {};
  const airdropTransferred = Array.isArray(airdrop.transferred) ? airdrop.transferred : [];
  const airdropFailed = Array.isArray(airdrop.failed) ? airdrop.failed : [];
  const deliveredAirdropWallets = new Set(
    airdropTransferred.map((row) => String(row?.wallet || '').trim()).filter(Boolean),
  );
  const airdropTransferTxCount = airdropTransferred
    .filter((row) => String(row?.txId || row?.signature || '').trim()).length;
  const demoAirdropComplete = plannedAirdropCount <= 0 || Boolean(
    airdropFailed.length === 0
    && airdropTransferred.length >= plannedAirdropCount
    && deliveredAirdropWallets.size >= plannedAirdropCount
    && airdropTransferTxCount >= plannedAirdropCount
  );
  const positionRows = results.flatMap((pool) => [
    ...(Array.isArray(pool?.mainPositions) ? pool.mainPositions : []),
    ...(Array.isArray(pool?.ladderPositions) ? pool.ladderPositions : []),
    ...(Array.isArray(pool?.supportPositions) ? pool.supportPositions : []),
    ...(pool?.bootstrap ? [pool.bootstrap] : []),
  ]);
  const lockedFeeKeyRows = positionRows.filter((position) => position?.locked === true);
  const demoLiquidityComplete = Boolean(
    resultCount > 0
    && positionRows.length > 0
    && lockedFeeKeyRows.length === positionRows.length
    && lockedFeeKeyRows.every((position) => String(position?.feeKeyNftMint || position?.feeKeyMint || '').trim()),
  );
  const feeKeyRecipientRows = positionRows.filter((position) => String(position?.recipient || '').trim());
  const demoFeeKeyRecipientsComplete = feeKeyRecipientRows.every((position) => {
    const recipient = String(position?.recipient || '').trim();
    const transferredTo = String(position?.transferredTo || '').trim();
    const transferTx = String(position?.transferTx || position?.txIds?.transfer || '').trim();
    return Boolean(recipient && transferredTo === recipient && transferTx);
  });
  return Boolean(
    tokenMint
    && demoLiquidityComplete
    && demoFeeKeyRecipientsComplete
    && demoAirdropComplete
    && transferHasWalletEmptyFinalSweepEvidence(run.transfer)
    && readiness.completed === true
    && readiness.completionStatus === 'complete'
    && completion.terminalSweepEvidence === true
    && readiness.nextEndpoint == null
    && (!sweepPhase || sweepPhase.state === 'complete')
  );
}

function stableFundingFingerprintValue(value) {
  if (Array.isArray(value)) return value.map(stableFundingFingerprintValue);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((record, key) => {
      const stable = stableFundingFingerprintValue(value[key]);
      if (stable !== undefined) record[key] = stable;
      return record;
    }, {});
  }
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string' || typeof value === 'boolean' || value === null) return value;
  if (value === undefined) return undefined;
  return String(value);
}

function fundingEstimateAllocationsForTopology(topology = {}) {
  const pools = Array.isArray(topology.pools) ? topology.pools : [];
  return pools.map((pool) => {
    const quoteDecimalsOverride = optionalDecimals(pool.quoteDecimalsOverride ?? pool.quoteDecimals);
    // Only a hand-set price is part of the plan. The live price from the
    // pair-token check changes every minute; including it made every
    // re-check mark the estimate stale (and mid-launch, sent the user back
    // to Fund). The server probes live prices itself.
    const quoteUsdOverride = Number.isFinite(Number(pool.quoteUsdOverride)) && Number(pool.quoteUsdOverride) > 0
      ? Number(pool.quoteUsdOverride)
      : undefined;
    return {
      quoteToken: pool.quoteToken,
      quoteMint: pool.quoteMint || undefined,
      supplyPercent: pool.supplyPercent,
      ammConfigIndex: pool.ammConfigIndex,
      quoteUsdOverride,
      quoteDecimalsOverride,
      quoteSymbolOverride: pool.quoteSymbol,
      distribution: pool.distribution,
      bootstrap: pool.bootstrap,
      ladder: pool.ladder,
      support: pool.support,
      ...(pool.venue === 'meteora-damm-v2' ? { venue: pool.venue, damm: pool.damm } : {}),
    };
  });
}

function fundingEstimateTokenSupply(value) {
  const cleaned = String(value ?? '').replace(/[^\d]/g, '');
  return cleaned || '1000000000';
}

function launchPlanLogoFingerprint(logo = null) {
  if (!logo || typeof logo !== 'object') return null;
  return {
    name: logo.name || null,
    mimeType: logo.mimeType || logo.type || null,
    sizeBytes: Number.isFinite(Number(logo.sizeBytes ?? logo.size))
      ? Number(logo.sizeBytes ?? logo.size)
      : null,
  };
}

function launchPlanConfigFingerprint(config = currentLaunchConfig()) {
  const token = config?.token || {};
  const topology = config?.poolTopology || {};
  return JSON.stringify(stableFundingFingerprintValue({
    experience: config?.experience || null,
    token: {
      name: token.name || null,
      symbol: token.symbol || null,
      supply: fundingEstimateTokenSupply(token.supply),
      description: token.description || null,
      decimals: token.decimals ?? 9,
      mintFormat: token.mintFormat === 'classic-spl' ? 'classic-spl' : 'token-2022',
      logo: launchPlanLogoFingerprint(token.logo),
      ...(token.sealedLaunch === true ? { sealedLaunch: true } : {}),
    },
    launchSol: Number.isFinite(Number(config?.launchSol)) ? Number(config.launchSol) : null,
    mode: config?.mode || null,
    vanity: config?.vanity || null,
    poolTopology: topology,
    funding: {
      launchSol: Number.isFinite(Number(config?.funding?.launchSol ?? config?.launchSol))
        ? Number(config.funding?.launchSol ?? config.launchSol)
        : null,
      targetMarketCapUsd: Number.isFinite(Number(config?.funding?.targetMarketCapUsd ?? topology.targetMarketCapUsd))
        ? Number(config?.funding?.targetMarketCapUsd ?? topology.targetMarketCapUsd)
        : null,
    },
  }));
}

function launchPlanWalletFingerprint(walletPublicKey) {
  return String(walletPublicKey || '').trim() || null;
}

function stampLaunchPlanConfigFingerprint(plan, config = currentLaunchConfig(), walletPublicKey = selectedLaunchWalletPublicKey()) {
  if (!plan || typeof plan !== 'object') return plan;
  return {
    ...plan,
    v2LaunchConfigFingerprint: launchPlanConfigFingerprint(config),
    v2LaunchWalletFingerprint: launchPlanWalletFingerprint(walletPublicKey),
  };
}

function launchPlanOperationSequenceStatus(operations = []) {
  const operationIds = (Array.isArray(operations) ? operations : [])
    .map((operation) => String(operation?.id || '').trim())
    .filter(Boolean);
  const missingOperationIds = V2_REQUIRED_LAUNCH_PLAN_OPERATION_IDS
    .filter((id) => !operationIds.includes(id));
  let cursor = -1;
  const ordered = V2_REQUIRED_LAUNCH_PLAN_OPERATION_IDS.every((id) => {
    const index = operationIds.indexOf(id);
    if (index <= cursor) return false;
    cursor = index;
    return true;
  });
  return {
    operationIds,
    missingOperationIds,
    ordered,
    ready: missingOperationIds.length === 0 && ordered,
  };
}

function localApiLaunchPlanStatus(plan = state.launchPlan, config = currentLaunchConfig()) {
  const expectedFingerprint = launchPlanConfigFingerprint(config);
  const actualFingerprint = String(plan?.v2LaunchConfigFingerprint || '').trim();
  const expectedWalletFingerprint = launchPlanWalletFingerprint(selectedLaunchWalletPublicKey());
  const actualWalletFingerprint = launchPlanWalletFingerprint(plan?.v2LaunchWalletFingerprint);
  const isLocalApiPlan = state.apiStatus === 'connected' && plan?.source === 'local-api';
  const operations = Array.isArray(plan?.operations) ? plan.operations : [];
  const sequence = launchPlanOperationSequenceStatus(operations);
  const decodedOperationEvidence = Boolean(operations.length && operations.every((operation) => (
    operation?.kind === 'local-wallet-operation'
    && operation?.source === 'v2-launch-plan'
    && operation?.signer === 'trebuchet-managed-launch-wallet'
    && operation?.simulation?.decoded === true
  )));
  const operationSequenceEvidence = Boolean(decodedOperationEvidence && sequence.ready);
  const matchesConfig = Boolean(isLocalApiPlan && actualFingerprint && actualFingerprint === expectedFingerprint);
  const matchesWallet = Boolean(
    isLocalApiPlan
    && expectedWalletFingerprint
    && actualWalletFingerprint
    && actualWalletFingerprint === expectedWalletFingerprint
  );
  const ready = Boolean(matchesConfig && matchesWallet && operationSequenceEvidence);
  return {
    isLocalApiPlan,
    expectedFingerprint,
    actualFingerprint,
    expectedWalletFingerprint,
    actualWalletFingerprint,
    matchesConfig,
    matchesWallet,
    decodedOperationEvidence,
    operationSequenceEvidence,
    operationIds: sequence.operationIds,
    missingOperationIds: sequence.missingOperationIds,
    operationSequenceOrdered: sequence.ordered,
    operationCount: operations.length,
    ready,
    stale: Boolean(isLocalApiPlan && (!matchesConfig || !matchesWallet)),
    incomplete: Boolean(matchesConfig && matchesWallet && !operationSequenceEvidence),
  };
}

function classicFundingEstimateRequest(config = currentLaunchConfig()) {
  const topology = config?.poolTopology || {};
  const token = config?.token || {};
  const preallocation = topology.preallocation || {};
  const airdrop = topology.airdrop || {};
  return {
    allocations: stableFundingFingerprintValue(fundingEstimateAllocationsForTopology(topology)),
    targetMarketCapUsd: Number(topology.targetMarketCapUsd || 0),
    publishLaunchReport: topology.report?.publish !== false,
    token: {
      supply: fundingEstimateTokenSupply(token.supply),
      decimals: 9,
    },
    preallocation: {
      enabled: preallocation.enabled === true || Number(preallocation.supplyPercent || 0) > 0,
      supplyPercent: Number(preallocation.supplyPercent || 0),
      source: preallocation.source || null,
    },
    airdrop: {
      enabled: airdrop.enabled === true,
      recipientCount: Number(airdrop.recipientCount || 0),
      supplyPercent: Number(airdrop.supplyPercent || 0),
      executionCostSol: Number(airdrop.executionCostSol || 0),
    },
  };
}

// The server's readiness check decides whether an estimate is current, so the screen asks the same
// core function: a second copy here normalized support layers differently and every preset launch
// was blocked as "estimate stale" while the screen called it covered.
function classicFundingEstimateFingerprint(config = currentLaunchConfig()) {
  if (typeof TrebuchetCore !== 'undefined' && typeof TrebuchetCore.v2FundingEstimateFingerprint === 'function') {
    return TrebuchetCore.v2FundingEstimateFingerprint(config);
  }
  return JSON.stringify(stableFundingFingerprintValue(classicFundingEstimateRequest(config)));
}

function classicFundingEstimateStatus(config = currentLaunchConfig(), estimate = state.classicFundingEstimate) {
  const hasEstimate = Number(estimate?.totalSol || 0) > 0;
  const expectedFingerprint = classicFundingEstimateFingerprint(config);
  const actualFingerprint = String(estimate?.v2FundingFingerprint || '').trim();
  const matchesConfig = Boolean(hasEstimate && actualFingerprint && actualFingerprint === expectedFingerprint);
  return {
    estimate,
    hasEstimate,
    matchesConfig,
    stale: Boolean(hasEstimate && !matchesConfig),
    expectedFingerprint,
    actualFingerprint,
  };
}

function stampClassicFundingEstimate(estimate, config = currentLaunchConfig()) {
  if (!estimate || typeof estimate !== 'object') return estimate;
  return {
    ...estimate,
    v2FundingFingerprint: classicFundingEstimateFingerprint(config),
    v2FundingInputs: classicFundingEstimateRequest(config),
  };
}

function currentClassicFundingEstimateForConfig(config = currentLaunchConfig()) {
  return classicFundingEstimateStatus(config).matchesConfig ? state.classicFundingEstimate : null;
}

function proofLaunchConfigSnapshotState(proof = currentLaunchProof()) {
  const launchConfig = proof?.launchConfig && typeof proof.launchConfig === 'object'
    ? proof.launchConfig
    : null;
  const missing = [];
  const mismatches = [];
  const textMatches = (left, right) => {
    const a = String(left ?? '').trim();
    const b = String(right ?? '').trim();
    return !a || !b || a === b;
  };
  const numbersMatch = (left, right) => {
    if (left == null || left === '' || right == null || right === '') return true;
    const a = Number(left);
    const b = Number(right);
    if (!Number.isFinite(a) || !Number.isFinite(b)) return String(left ?? '').trim() === String(right ?? '').trim();
    return Math.abs(a - b) < 1e-9;
  };
  const requiredTextMatches = (left, right) => {
    const a = String(left ?? '').trim();
    const b = String(right ?? '').trim();
    return Boolean(a && b && a === b);
  };
  const requiredNumbersMatch = (left, right) => (
    left != null && left !== ''
    && right != null && right !== ''
    && numbersMatch(left, right)
  );
  const textMatchesWhenSnapshotPresent = (left, right) => String(left ?? '').trim()
    ? requiredTextMatches(left, right)
    : true;
  const numbersMatchWhenSnapshotPresent = (left, right) => left != null && left !== ''
    ? requiredNumbersMatch(left, right)
    : true;
  const poolRowsMatch = (snapshotPool = {}, journalPool = {}) => (
    requiredTextMatches(snapshotPool.quoteToken || snapshotPool.quoteSymbol, journalPool.quoteToken || journalPool.quoteSymbol || journalPool.quote)
    && textMatchesWhenSnapshotPresent(snapshotPool.quoteMint, journalPool.quoteMint)
    && requiredNumbersMatch(snapshotPool.supplyPercent, journalPool.supplyPercent)
    && numbersMatchWhenSnapshotPresent(snapshotPool.ammConfigIndex, journalPool.ammConfigIndex)
  );
  if (!launchConfig) {
    return { state: 'missing', complete: false, missing: ['snapshot'] };
  }
  if (
    String(launchConfig.schema || '').trim() !== 'trebuchet-v2-launch-config'
    || String(launchConfig.source || '').trim() !== 'trebuchet-v2'
  ) {
    missing.push('Trebuchet snapshot marker');
  }
  const token = launchConfig.token && typeof launchConfig.token === 'object'
    ? launchConfig.token
    : null;
  const topology = launchConfig.poolTopology && typeof launchConfig.poolTopology === 'object'
    ? launchConfig.poolTopology
    : null;
  if (!token) {
    missing.push('token');
  } else {
    if (!String(token.name || token.symbol || '').trim()) missing.push('token identity');
    if (!String(token.supply ?? '').trim()) missing.push('token supply');
  }
  if (!topology) {
    missing.push('pool topology');
  } else if (!Array.isArray(topology.pools) || topology.pools.length === 0) {
    missing.push('planned pools');
  }
  if (token && proof?.token && typeof proof.token === 'object') {
    if (!requiredTextMatches(token.name, proof.token.name)) mismatches.push('token name');
    if (!requiredTextMatches(token.symbol, proof.token.symbol)) mismatches.push('token symbol');
    if (!requiredNumbersMatch(token.supply, proof.token.totalSupply ?? proof.token.supply)) mismatches.push('token supply');
    if (!requiredNumbersMatch(token.decimals, proof.token.decimals)) mismatches.push('token decimals');
  }
  const snapshotPools = topology && Array.isArray(topology.pools) ? topology.pools : [];
  const journalPools = Array.isArray(proof?.poolPlan?.allocations) ? proof.poolPlan.allocations : [];
  if (snapshotPools.length > 0 && journalPools.length > 0) {
    if (snapshotPools.length !== journalPools.length) {
      mismatches.push('planned pool count');
    } else {
      snapshotPools.forEach((pool, index) => {
        if (!poolRowsMatch(pool, journalPools[index])) {
          mismatches.push(`planned pool ${index + 1}`);
        }
      });
    }
  }
  return {
    state: missing.length ? 'incomplete' : mismatches.length ? 'mismatch' : 'complete',
    complete: missing.length === 0 && mismatches.length === 0,
    missing,
    mismatches,
  };
}

function buildClassicRetirementGate(proof = currentLaunchProof(), audit = null, config = currentLaunchConfig()) {
  config = proofConfigForFingerprint(proof, config);
  const expectedAuditFingerprint = launchProofFingerprint(proof, config);
  audit = reportParityAuditMatchesProof(audit, proof, config)
    ? audit
    : buildV2ReportParityAudit(proof, config);
  const results = Array.isArray(proof?.liquidity?.results) ? proof.liquidity.results : [];
  const plannedPools = buildV2ReportPoolPlan(config, results, proof);
  const plannedPoolCount = Math.max(1, plannedPools.length || 0);
  const plannedPositionCount = plannedPools.reduce((sum, pool) => sum + Number(pool.plannedPositionCount || 0), 0);
  const recordedPoolIds = launchProofPoolIds(proof);
  const poolCount = Number(proof?.liquidity?.poolCount || results.length || 0);
  const positionCount = proofPositions(results);
  const liquidityEvidence = comparisonLiquidityEvidenceState(proof, {
    plannedPoolCount,
    plannedPositionCount,
  });
  const recordedPositionCount = liquidityEvidence.positionCount;
  const lockedPositionCount = liquidityEvidence.lockedPositionCount;
  const feeKeyCount = liquidityEvidence.feeKeyCount;
  const txEvidence = v2LiquidityTransactionEvidenceCounts(results);
  const feeKeyRecipientTarget = txEvidence.feeKeyRecipientRows.length;
  const report = currentReportPublish(proof, config);
  const localDossier = currentLocalDossier(proof, config);
  const staleReport = staleReportPublishForProof(proof, config);
  const reportUri = report?.htmlUri || report?.jsonUri || null;
  const reportArtifactRecord = report || localDossier || null;
  const reportArtifact = reportUri || localDossier;
  const finalSweepComplete = transferHasWalletEmptyFinalSweepEvidence(proof?.transfer);
  const reportArtifactSweepBound = Boolean(
    finalSweepComplete
    && reportArtifactRecord
    && reportArtifactMatchesTerminalSweep(reportArtifactRecord, proof)
  );
  const isDemoProof = isDemoLaunchProof(proof);
  const proofLaunchConfigSnapshot = proofLaunchConfigSnapshotState(proof);
  const proofJournalEvidence = Boolean(proof?.journalId);
  const localJournalEvidenceState = proofJournalEvidenceState(proof);
  const matchingLocalJournal = localJournalEvidenceState.journal;
  const proofTerminalJournalEvidence = proofHasTerminalLaunchJournal(proof);
  const proofWalletEvidence = Boolean(proof?.walletPublicKey);
  const liveTokenAuthorityFields = ['mintAuthorityRenounced', 'freezeAuthorityDisabled', 'metadataUpdateAuthorityRevoked', 'metadataImmutable'];
  const liveTokenAuthorityPassCount = liveTokenAuthorityFields.filter((field) => proof?.token?.[field] === true).length;
  const liveTokenAuthorityComplete = liveTokenAuthorityPassCount === liveTokenAuthorityFields.length;
  const livePoolIdentityComplete = Boolean(
    plannedPoolCount > 0
    && recordedPoolIds.length === plannedPoolCount
    && poolCount === plannedPoolCount
    && txEvidence.poolCreateTxCount >= plannedPoolCount
    && !liquidityEvidence.missing.includes('pool count')
  );
  const livePositionProofComplete = Boolean(
    plannedPositionCount > 0
    && recordedPositionCount >= plannedPositionCount
    && txEvidence.openTxCount >= recordedPositionCount
    && !liquidityEvidence.missing.some((item) => ['position count', 'position records'].includes(item))
  );
  const liveLockProofComplete = Boolean(
    recordedPositionCount > 0
    && lockedPositionCount >= recordedPositionCount
    && txEvidence.lockTxCount >= recordedPositionCount
    && !liquidityEvidence.missing.includes('lock count')
    && feeKeyCount >= lockedPositionCount
    && !liquidityEvidence.missing.includes('fee key count')
    && txEvidence.feeKeyRecipientTransferred >= feeKeyRecipientTarget
  );
  const liveLiquidityProofComplete = Boolean(livePoolIdentityComplete && livePositionProofComplete && liveLockProofComplete);
  const hasCompletedLiveProof = Boolean(
    proof
    && !isDemoProof
    && proofLaunchConfigSnapshot.complete
    && proofJournalEvidence
    && proofTerminalJournalEvidence
    && proofWalletEvidence
    && proof?.token?.mint
    && liveTokenAuthorityComplete
    && liveLiquidityProofComplete
    && finalSweepComplete,
  );
  const requirements = [
    {
      id: 'live-proof',
      pass: hasCompletedLiveProof,
      detail: hasCompletedLiveProof
        ? `Live Trebuchet proof has ${poolCount} pool${poolCount === 1 ? '' : 's'} and ${positionCount} position${positionCount === 1 ? '' : 's'}.`
        : isDemoProof
          ? 'Test launch record proves wiring only; run a real Trebuchet launch.'
          : proof && proofLaunchConfigSnapshot.state === 'missing'
            ? 'Completed proof is missing its frozen launch-config snapshot; load proof-bound config.'
            : proof && proofLaunchConfigSnapshot.state === 'mismatch'
              ? `Completed proof has a mismatched frozen launch-config snapshot (${proofLaunchConfigSnapshot.mismatches.join(', ')}); load the journal-bound token and pool configuration.`
            : proof && !proofLaunchConfigSnapshot.complete
              ? `Completed proof has an incomplete frozen launch-config snapshot (${proofLaunchConfigSnapshot.missing.join(', ')}); load proof-bound token and pool configuration.`
            : proof && !proofJournalEvidence
              ? 'Completed proof is missing its launch journal id; load journal-backed proof.'
            : proof && !matchingLocalJournal
              ? `Completed proof journal ${proof.journalId} is not loaded from the local launch-journal store; refresh local recovery state.`
            : proof && localJournalEvidenceState.mismatches.length
              ? `Loaded launch journal does not match proof (${localJournalEvidenceState.mismatches.join(', ')}); refresh local recovery state.`
            : proof && localJournalEvidenceState.missing.length
              ? `Loaded launch journal is missing proof backing (${localJournalEvidenceState.missing.join(', ')}); refresh local recovery state.`
            : proof && !proofTerminalJournalEvidence
              ? `Launch journal is not terminal (${proof?.status || 'unknown'} / ${proof?.stage || 'unknown'}); refresh proof after final sweep.`
            : proof && !proofWalletEvidence
              ? 'Completed proof is missing its launch wallet; load wallet-bound proof.'
          : proof?.token?.mint && !liveTokenAuthorityComplete
                ? `Token authority proof is ${liveTokenAuthorityPassCount}/${liveTokenAuthorityFields.length}; complete authority evidence.`
          : proof && (!livePoolIdentityComplete && (recordedPoolIds.length !== plannedPoolCount || poolCount !== plannedPoolCount || liquidityEvidence.missing.includes('pool count')))
            ? `Pool identity proof is ${recordedPoolIds.length}/${plannedPoolCount}; load exact recorded pool IDs.`
          : proof && txEvidence.poolCreateTxCount < plannedPoolCount
            ? `Pool-create transaction proof is ${txEvidence.poolCreateTxCount}/${plannedPoolCount}; refresh journal-backed liquidity proof.`
          : proof && !livePositionProofComplete && (recordedPositionCount < plannedPositionCount || liquidityEvidence.missing.some((item) => ['position count', 'position records'].includes(item)))
            ? `Position proof is ${recordedPositionCount}/${plannedPositionCount}; load exact position records.`
          : proof && txEvidence.openTxCount < recordedPositionCount
            ? `Position-open transaction proof is ${txEvidence.openTxCount}/${recordedPositionCount}; refresh journal-backed liquidity proof.`
          : proof && !liveLockProofComplete && (lockedPositionCount < recordedPositionCount || liquidityEvidence.missing.includes('lock count'))
            ? `Burn & Earn lock proof is ${lockedPositionCount}/${recordedPositionCount}; complete lock evidence.`
          : proof && txEvidence.lockTxCount < recordedPositionCount
            ? `Burn & Earn lock transaction proof is ${txEvidence.lockTxCount}/${recordedPositionCount}; refresh journal-backed liquidity proof.`
          : proof && !liveLockProofComplete && (feeKeyCount < lockedPositionCount || liquidityEvidence.missing.includes('fee key count'))
            ? `Fee Key NFT proof is ${feeKeyCount}/${lockedPositionCount}; complete Fee Key mint evidence.`
          : proof && txEvidence.feeKeyRecipientTransferred < feeKeyRecipientTarget
            ? `Fee Key recipient transfer proof is ${txEvidence.feeKeyRecipientTransferred}/${feeKeyRecipientTarget}; complete recipient delivery evidence.`
          : proof?.transfer && !finalSweepComplete
            ? 'Final sweep record is not terminal; verify wallet-empty, error-free sweep evidence.'
            : 'Run a real Trebuchet launch through token, liquidity, and final sweep.',
    },
    {
      id: 'report-proof',
      pass: Boolean(reportArtifact && reportArtifactSweepBound),
      detail: reportUri
        ? reportArtifactSweepBound
          ? `Permanent report proof is attached: ${fullAddress(reportUri)}.`
          : 'Permanent report proof is missing the terminal sweep evidence hash; republish after final sweep.'
        : localDossier
          ? reportArtifactSweepBound
            ? `Saved launch record proof is attached: ${localDossier.filename}.`
            : 'Saved launch record proof is missing the terminal sweep evidence hash; download a fresh launch record after final sweep.'
        : staleReport
          ? reportPublishMatchesProof(staleReport, proof, config) && !reportArtifactMatchesTerminalSweep(staleReport, proof)
            ? localDossierHasEvidence(staleReport)
              ? 'Saved launch record proof is missing the terminal sweep evidence hash; download a fresh launch record after final sweep.'
              : 'Permanent report proof is missing the terminal sweep evidence hash; republish after final sweep.'
            : 'Report artifact belongs to another Trebuchet proof; regenerate it.'
          : 'Publish or attach a proof-bound Trebuchet launch report.',
    },
    {
      id: 'audit',
      pass: audit?.status === 'pass',
      detail: audit?.status === 'pass'
        ? 'The generated Trebuchet proof audit is fully passing.'
        : `Proof audit is ${audit?.status || 'missing'} with ${audit?.missingCount || 0} missing and ${audit?.warnCount || 0} warning checks.`,
    },
  ];
  const missing = requirements.filter((item) => !item.pass);
  const passCount = requirements.length - missing.length;
  return {
    id: 'classic-retirement',
    source: 'trebuchet-v2-classic-retirement-gate',
    proofFingerprint: expectedAuditFingerprint,
    auditFingerprint: audit?.proofFingerprint || null,
    title: missing.length ? 'Release evidence' : 'Ready to release',
    state: missing.length ? 'danger' : 'pass',
    badge: missing.length ? 'Blocked' : 'Ready',
    detail: missing.length ? missing[0].detail : 'Live launch, report and proof audit pass.',
    passCount,
    itemCount: requirements.length,
    requirements,
    replacementCriteria: [],
    criteriaPassCount: 0,
    criteriaItemCount: 0,
  };
}


// A wallet address anywhere on the page is one chip. Hovering or focusing it shows what the
// wallet holds now, read from the chain: SOL, each token, and open token accounts with their
// rent. It also says whether Trebuchet holds the wallet's key.

const WALLET_CONTENTS_MAX_AGE_MS = 15_000;
// The sweep drains to zero, so anything above a few transaction fees is worth sending on.
const SWEEP_DUST_LAMPORTS = 20_000;
const walletContentsCache = new Map();

function walletChipHtml(address, { label = '' } = {}) {
  const value = String(address || '').trim();
  if (!value) return '';
  return `<span class="wallet-chip" tabindex="0" data-wallet-chip="${escapeHtml(value)}" title="${escapeHtml(value)}">`
    + `<code>${escapeHtml(shortAddress(value))}</code>${label ? `<small>${escapeHtml(label)}</small>` : ''}</span>`;
}

function walletContents(address, { fresh = false } = {}) {
  const cached = walletContentsCache.get(address);
  if (!fresh && cached && (cached.pending || Date.now() - cached.at < WALLET_CONTENTS_MAX_AGE_MS)) return cached.pending || Promise.resolve(cached.value);
  if (state.apiStatus !== 'connected' || !state.apiClient?.getWalletContents) return Promise.resolve(null);
  const pending = state.apiClient.getWalletContents(address, { fresh })
    .then((value) => { walletContentsCache.set(address, { at: Date.now(), value }); return value; })
    .catch((error) => { walletContentsCache.delete(address); throw error; });
  walletContentsCache.set(address, { ...(cached || {}), pending });
  return pending;
}

function cachedWalletContents(address) {
  return walletContentsCache.get(address)?.value || null;
}

function walletTokenSymbol(mint) {
  return (state.coins?.list || []).find((coin) => coin.mint === mint)?.symbol || shortAddress(mint);
}

function formatSol(lamports) {
  return Number((Number(lamports || 0) / 1e9).toFixed(6)).toString();
}

// The sweep moves tokens and SOL, and closes empty token accounts to return their rent.
function walletSweepable(contents) {
  return Boolean(contents && contents.ownerProgram === '11111111111111111111111111111111'
    && (contents.tokens.length > 0 || contents.lamports >= SWEEP_DUST_LAMPORTS || contents.openAccounts > 0));
}

function walletContentsSummary(contents) {
  if (!contents) return '';
  return [
    `${formatSol(contents.lamports)} SOL`,
    contents.tokens.length ? `${contents.tokens.length} token${contents.tokens.length === 1 ? '' : 's'}` : null,
    contents.openAccounts ? `${contents.openAccounts} open account${contents.openAccounts === 1 ? '' : 's'}` : null,
  ].filter(Boolean).join(' · ');
}

const WALLET_KEY_LABELS = { launch: 'Launch wallet', retired: 'Finished launch wallet', vanity: 'Vanity address' };

function walletCardHtml(address, contents, error) {
  const rows = contents ? [
    ['SOL', formatSol(contents.lamports)],
    ...contents.tokens.map((token) => [walletTokenSymbol(token.mint), formatTokenAmount(token.amountRaw, token.decimals)]),
    contents.openAccounts ? ['Open token accounts', `${contents.openAccounts} · ${formatSol(contents.accountRentLamports)} SOL rent`] : null,
  ].filter(Boolean) : [];
  const kind = contents?.ownerProgram && contents.ownerProgram !== '11111111111111111111111111111111' && contents.lamports
    ? 'Program account'
    : contents?.key ? `${WALLET_KEY_LABELS[contents.key]} · key in Trebuchet` : contents ? 'Key not in Trebuchet' : '';
  return `
    <header><code>${escapeHtml(address)}</code>${kind ? `<span>${escapeHtml(kind)}</span>` : ''}</header>
    ${error ? `<p class="is-error">${escapeHtml(error)}</p>` : contents ? `<dl>${rows.map(([name, value]) => `<div><dt>${escapeHtml(name)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl>` : '<p><span class="rail-spin" aria-hidden="true"></span></p>'}
    <a href="${escapeHtml(solscanAccountUrl(address))}" target="_blank" rel="noopener">Solscan</a>`;
}

function walletChipCard() {
  let card = document.getElementById('walletChipCard');
  if (!card) {
    card = document.createElement('div');
    card.id = 'walletChipCard';
    card.className = 'wallet-chip-card';
    card.setAttribute('role', 'tooltip');
    card.hidden = true;
    card.addEventListener('mouseleave', () => hideWalletChipCard());
    document.body.appendChild(card);
  }
  return card;
}

let walletChipTarget = null;
let walletChipHideTimer = null;

function placeWalletChipCard(card, chip) {
  const box = chip.getBoundingClientRect();
  const width = Math.min(340, window.innerWidth - 32);
  card.style.width = `${width}px`;
  card.style.left = `${Math.max(16, Math.min(box.left, window.innerWidth - width - 16))}px`;
  const below = box.bottom + 6;
  card.style.top = `${below + card.offsetHeight > window.innerHeight - 8 ? Math.max(8, box.top - card.offsetHeight - 6) : below}px`;
}

function showWalletChipCard(chip) {
  clearTimeout(walletChipHideTimer);
  const address = chip.dataset.walletChip;
  const card = walletChipCard();
  walletChipTarget = chip;
  chip.setAttribute('aria-describedby', 'walletChipCard');
  card.innerHTML = walletCardHtml(address, cachedWalletContents(address), null);
  card.hidden = false;
  placeWalletChipCard(card, chip);
  walletContents(address)
    .then((contents) => { if (walletChipTarget === chip) { card.innerHTML = walletCardHtml(address, contents, null); placeWalletChipCard(card, chip); } })
    .catch((error) => { if (walletChipTarget === chip) card.innerHTML = walletCardHtml(address, null, error.message || 'Could not read this wallet'); });
}

function hideWalletChipCard({ now = false } = {}) {
  clearTimeout(walletChipHideTimer);
  const hide = () => {
    const card = document.getElementById('walletChipCard');
    if (card && !card.matches(':hover')) card.hidden = true;
    walletChipTarget?.removeAttribute('aria-describedby');
    walletChipTarget = null;
  };
  if (now) hide(); else walletChipHideTimer = setTimeout(hide, 150);
}

function bindWalletChips() {
  document.addEventListener('mouseover', (event) => {
    const chip = event.target.closest?.('[data-wallet-chip]');
    if (chip && chip !== walletChipTarget) showWalletChipCard(chip);
  });
  document.addEventListener('mouseout', (event) => {
    const chip = event.target.closest?.('[data-wallet-chip]');
    if (chip && !chip.contains(event.relatedTarget) && !event.relatedTarget?.closest?.('#walletChipCard')) hideWalletChipCard();
  });
  document.addEventListener('focusin', (event) => {
    const chip = event.target.closest?.('[data-wallet-chip]');
    if (chip) showWalletChipCard(chip);
  });
  document.addEventListener('focusout', (event) => {
    if (event.target.closest?.('[data-wallet-chip]')) hideWalletChipCard();
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && walletChipTarget) hideWalletChipCard({ now: true });
  });
}

// "Locked" only when unlocking the PIN would help. A wallet whose key cannot be
// read with the PIN already unlocked says so instead of pretending to be locked.
function walletLabelState(secretBlocked, unlocked, publicKey) {
  if (walletLockReason() === 'unreadable') return 'Key unreadable';
  return secretBlocked || !unlocked ? 'Locked' : shortAddress(publicKey);
}

// The Wallet screen reads the chain for the wallet it shows: SOL and every token it holds.
// Asked at most once every 30 seconds per wallet, and only while that screen is open.
function walletPanelBalance(publicKey) {
  const cached = state.walletPanel;
  if (cached && cached.publicKey === publicKey) return cached;
  return null;
}

function refreshWalletPanelBalance(publicKey) {
  if (!publicKey || state.activeView !== 'wallet') return;
  if (state.apiStatus !== 'connected' || !state.apiClient?.checkDetailedBalance) return;
  const cached = walletPanelBalance(publicKey);
  if (cached && (cached.loading || Date.now() - cached.at < 30000)) return;
  state.walletPanel = { ...(cached || {}), publicKey, loading: true, at: Date.now() };
  state.apiClient.checkDetailedBalance(publicKey)
    .then((balance) => { state.walletPanel = { publicKey, balance, loading: false, at: Date.now(), error: null }; })
    .catch((error) => { state.walletPanel = { publicKey, balance: cached?.balance || null, loading: false, at: Date.now(), error: error.message || 'Balance check failed' }; })
    .finally(() => { if (state.activeView === 'wallet') renderWallet(); });
}

function walletHoldingRows(balance) {
  const coinSymbol = (mint) => (state.coins?.list || []).find((coin) => coin.mint === mint)?.symbol || null;
  return Object.entries(balance?.tokens && typeof balance.tokens === 'object' ? balance.tokens : {})
    .filter(([, token]) => Number(token?.amountUi) > 0)
    .map(([mint, token]) => ({ mint, symbol: coinSymbol(mint) || token.symbol || shortAddress(mint), amount: Number(token.amountUi) }))
    .sort((a, b) => b.amount - a.amount);
}

function renderWallet() {
  const current = account();
  const unlocked = walletIsUnlocked();
  const walletRows = walletAccounts();
  const selectedPublicKey = selectedLaunchWalletPublicKey();
  const selectedRow = (
    selectedPublicKey
      ? walletRows.find((item) => item.publicKey === selectedPublicKey || item.id === selectedPublicKey)
      : null
  ) || walletRows[0] || null;
  const lockReason = selectedRow ? walletLockInfo(selectedRow) : { state: null, canUnlock: true };
  const keyGone = lockReason.state === 'missing' || lockReason.state === 'wrong-key';
  const secretBlocked = !keyGone && (state.secretPin.locked || selectedRow?.secretPinLocked === true);
  // Even when this wallet's key is gone, a locked PIN is still the way into every other saved key.
  const pinLockedForUnlock = keyGone && state.secretPin.configured && state.secretPin.locked && !state.secretPin.damaged;
  $('#walletLabel').textContent = selectedPublicKey
    ? `${selectedRow?.name || current.name} ${keyGone ? lockReason.label : walletLabelState(secretBlocked, unlocked, selectedPublicKey)}`
    : 'Choose launch wallet';
  $('.wallet-led').classList.toggle('is-on', Boolean(selectedPublicKey && unlocked && !secretBlocked));
  const activeRarity = selectedRow?.rarity || 'Common';
  const activeRarityGrade = selectedRow?.rarityGrade || 'common';
  const activeRarityClass = `wallet-rarity-${activeRarityGrade}`;
  const walletView = $('#view-wallet');
  const walletButton = $('#walletButton');
  [walletView, walletButton].forEach((element) => {
    if (!element) return;
    element.classList.remove(...WALLET_RARITY_CLASSES);
    if (selectedRow) element.classList.add(activeRarityClass);
  });
  if (walletButton) {
    const walletButtonLabel = !selectedRow
      ? 'Choose a launch wallet'
      : keyGone
        ? lockReason.detail
      : secretBlocked || !unlocked
        ? `Unlock ${selectedRow.name || 'launch wallet'} with Recovery PIN`
        : `Open ${selectedRow.name || 'launch wallet'}`;
    walletButton.title = walletButtonLabel;
    walletButton.setAttribute('aria-label', walletButtonLabel);
    walletButton.dataset.locked = secretBlocked || !unlocked ? 'true' : 'false';
  }
  const activeRarityBadge = $('#activeWalletRarityBadge');
  if (activeRarityBadge) {
    activeRarityBadge.className = `risk-badge wallet-rarity-badge${selectedRow ? ` ${activeRarityClass}` : ''}`;
    activeRarityBadge.textContent = selectedRow ? activeRarity : '';
    // A rarity grade only means something for a vanity address.
    activeRarityBadge.hidden = !selectedRow || /^common$/i.test(String(activeRarity || ''));
  }
  const rawWallet = selectedManagedWallet();
  const qrCode = rawWallet?.qrCode || (
    state.walletQr.publicKey === selectedPublicKey ? state.walletQr.qrCode : null
  );
  const qrLoading = state.walletQr.publicKey === selectedPublicKey && state.walletQr.loading;
  const qrError = state.walletQr.publicKey === selectedPublicKey ? state.walletQr.error : null;
  const revealed = state.revealedWallet?.publicKey === selectedPublicKey ? state.revealedWallet : null;
  const secretKeyB58 = revealed?.secretKeyB58 || '';
  const secretKeyJson = Array.isArray(revealed?.secretKey) ? JSON.stringify(revealed.secretKey) : '';
  const mnemonic = revealed?.mnemonic || '';
  const revealBusy = state.revealingWalletPublicKey === selectedPublicKey;
  const discardBusy = state.discardingWalletPublicKey === selectedPublicKey;
  const revealError = state.revealError && !revealed ? state.revealError : null;

  const proof = currentLaunchProof();
  const proofMint = proof?.token?.mint || proof?.mint || null;
  const proofPools = launchProofPoolIds(proof);
  const proofReportUri = proof?.report?.jsonUri || proof?.reportPublish?.jsonUri || null;
  // A simulated run produces no chain evidence, so none of its artifacts may
  // claim 'Verified' — that word is reserved for proof-layer evidence.
  const proofIsDemo = isDemoLaunchProof(proof);
  const proofAssetState = proofIsDemo ? 'Test' : 'Verified';
  const proofAssets = proof ? [
    proofMint ? {
      kind: 'token',
      type: proofIsDemo ? 'Token (test)' : 'Token proof',
      name: proof?.token?.symbol || shortAddress(proofMint),
      detail: proofMint,
      state: proofAssetState,
    } : null,
    proofPools.length ? {
      kind: 'liquidity',
      type: proofIsDemo ? 'Liquidity (test)' : 'Liquidity proof',
      name: `${proofPools.length} recorded pool${proofPools.length === 1 ? '' : 's'}`,
      detail: proofPools.map(shortAddress).join(', '),
      state: proofAssetState,
    } : null,
    proofReportUri ? {
      kind: 'report',
      type: proofIsDemo ? 'Launch report (test)' : 'Launch report',
      name: proofIsDemo ? 'Simulated report artifact' : 'Published report artifact',
      detail: proofReportUri,
      state: proofAssetState,
    } : null,
  ].filter(Boolean) : [];
  refreshHeldWallets();
  renderHeldWallets();
  $('#accountList').innerHTML = walletRows.map((item) => {
    const isActive = item.publicKey === selectedPublicKey;
    return `
      <article class="account-row wallet-rarity-${escapeHtml(item.rarityGrade)} ${isActive ? 'is-active' : ''}">
        <span class="ident">${escapeHtml(item.name.slice(0, 1))}</span>
        <span class="account-copy">
          <h3>${escapeHtml(item.name)}</h3>
          <p>${item.publicKey ? walletChipHtml(item.publicKey) : escapeHtml(item.address)}</p>
        </span>
        <span class="balance">
          <strong>${Number(item.balance || 0).toFixed(2)} SOL</strong>
          <span class="wallet-rarity-label">${[isActive ? 'In use' : null, /^common$/i.test(String(item.rarity || '')) ? null : item.rarity].filter(Boolean).map(escapeHtml).join(' · ')}</span>
        </span>
        <button class="pill-button" type="button" data-action="select-account" data-account="${escapeHtml(item.id)}">Select</button>
      </article>
    `;
  }).join('') || '<div class="empty-state">Create or import a launch wallet.</div>';

  refreshWalletPanelBalance(selectedPublicKey);
  const panel = selectedPublicKey ? walletPanelBalance(selectedPublicKey) : null;
  const solBalance = panel?.balance ? Number(panel.balance.sol) : null;
  const holdings = walletHoldingRows(panel?.balance);
  const spend = observedExecutionSpendSummary();
  const net = spend.inflowSol - spend.outflowSol;
  const sol4 = (value) => Number(value || 0).toFixed(4);
  const launchedCoins = (state.coins?.list || []).filter((coin) => coin.launchedHere && coin.mint).slice(0, 6);
  const stat = (label, value, unit = '', tone = '') => `<div class="wallet-stat${tone ? ` is-${tone}` : ''}"><span>${escapeHtml(label)}</span><b>${value}</b>${unit ? `<i>${escapeHtml(unit)}</i>` : ''}</div>`;
  $('#walletDetailPanel').innerHTML = selectedPublicKey && selectedRow ? `
    <header class="wallet-head">
      <span class="wallet-head-name"><strong>${escapeHtml(selectedRow.name)}</strong><span>${escapeHtml(shortAddress(selectedPublicKey))}</span></span>
      <span class="wallet-head-actions">
        <button class="pill-button" type="button" data-action="copy-wallet-address"><i class="fa-solid fa-copy"></i><span>Copy</span></button>
        <button class="pill-button" type="button" data-action="${secretBlocked || pinLockedForUnlock ? 'unlock-secret-pin' : 'reveal-wallet-secret'}" ${revealBusy || state.secretPin.busy || (keyGone && !pinLockedForUnlock) ? 'disabled' : ''}>
          <i class="fa-solid fa-key"></i><span>${revealBusy ? 'Revealing' : secretBlocked || pinLockedForUnlock ? 'Unlock PIN' : revealed ? 'Reveal again' : 'Reveal'}</span>
        </button>
        <button class="pill-button danger" type="button" data-action="discard-wallet" ${discardBusy || state.fullRunRunning || state.realExecutionRunning ? 'disabled' : ''}>
          <i class="fa-solid fa-eye-slash"></i><span>${discardBusy ? 'Hiding' : 'Hide'}</span>
        </button>
      </span>
    </header>
    ${keyGone ? `<p class="wallet-detail-error">${escapeHtml(lockReason.detail)}</p>` : ''}
    <div class="wallet-stats">
      ${stat('SOL', solBalance != null ? sol4(solBalance) : (panel?.loading ? '…' : '—'), '', 'main')}
      ${stat('Tokens', String(holdings.length))}
      ${stat('Spent', spend.measuredCount ? sol4(spend.outflowSol) : '—', spend.measuredCount ? 'SOL' : '')}
      ${stat('Returned', spend.measuredCount ? sol4(spend.inflowSol) : '—', spend.measuredCount ? 'SOL' : '')}
      ${stat('Net', spend.measuredCount ? `${net >= 0 ? '+' : '−'}${sol4(Math.abs(net))}` : '—', spend.measuredCount ? 'SOL' : '', spend.measuredCount ? (net >= 0 ? 'ok' : 'warn') : '')}
    </div>
    ${panel?.error ? `<p class="wallet-detail-error">${escapeHtml(panel.error)}</p>` : ''}
    <div class="wallet-cols">
      <section class="wallet-block" aria-label="Holdings">
        <div class="wallet-block-head"><span>Holdings</span><small>${holdings.length ? `${holdings.length} token${holdings.length === 1 ? '' : 's'}` : ''}</small></div>
        <div class="wallet-line"><span>SOL</span><b>${solBalance != null ? sol4(solBalance) : '—'}</b></div>
        ${holdings.slice(0, 5).map((item) => `<div class="wallet-line"><span title="${escapeHtml(item.mint)}">${escapeHtml(item.symbol)}</span><b>${escapeHtml(item.amount.toLocaleString('en-US', { maximumFractionDigits: 2 }))}</b></div>`).join('')}
        ${holdings.length > 5 ? `<div class="wallet-line is-muted"><span>+${holdings.length - 5} more</span></div>` : ''}
      </section>
      <section class="wallet-block" aria-label="Coins">
        <div class="wallet-block-head"><span>Coins</span><small>${launchedCoins.length || ''}</small></div>
        ${launchedCoins.length ? launchedCoins.map((coin) => `<button class="wallet-line is-action" type="button" data-action="open-coin" data-coin-key="${escapeHtml(coin.key)}"><span>${escapeHtml(coin.symbol ? `$${coin.symbol}` : (coin.name || shortAddress(coin.mint)))}</span><b>${escapeHtml(coin.practice ? 'Test' : (coin.status || 'On-chain'))}</b></button>`).join('')
          : '<div class="wallet-line is-muted"><span>None launched</span></div>'}
      </section>
    </div>
    <section class="wallet-deposit" aria-label="Deposit">
      <div class="wallet-qr-box ${qrCode ? 'has-qr' : ''}">
        ${qrCode
          ? `<img src="${escapeHtml(qrCode)}" alt="Funding QR code for ${escapeHtml(fullAddress(selectedPublicKey))}">`
          : `<button class="pill-button" type="button" data-action="load-wallet-qr" ${qrLoading ? 'disabled' : ''}><i class="fa-solid ${qrLoading ? 'fa-spinner fa-spin' : 'fa-qrcode'}"></i><span>QR</span></button>`}
      </div>
      <div class="wallet-deposit-main">
        <span class="wallet-block-head"><span>Deposit address</span></span>
        <code>${escapeHtml(selectedPublicKey)}</code>
        ${qrError ? `<p class="wallet-detail-error">${escapeHtml(qrError)}</p>` : ''}
        ${renderFundingWalletHint()}
      </div>
    </section>
    ${renderSolflarePanel()}
    ${revealError ? `<p class="wallet-detail-error">${escapeHtml(revealError)}</p>` : ''}
    ${revealed ? `<div class="wallet-recovery-box is-revealed">
      <div>
        <span class="eyebrow">Wallet secret</span>
        <p>Anyone with this can take the wallet's funds. Keep it out of screenshots.</p>
      </div>
        <div class="secret-stack">
          ${mnemonic ? `
            <div class="secret-value">
              <span>Mnemonic</span>
              <code>${escapeHtml(mnemonic)}</code>
              <button class="pill-button" type="button" data-action="copy-wallet-secret" data-secret-type="mnemonic">
                <i class="fa-solid fa-copy"></i><span>Copy</span>
              </button>
            </div>
          ` : ''}
          ${secretKeyB58 ? `
            <div class="secret-value">
              <span>Base58 secret</span>
              <code>${escapeHtml(secretKeyB58)}</code>
              <button class="pill-button" type="button" data-action="copy-wallet-secret" data-secret-type="secretKeyB58">
                <i class="fa-solid fa-copy"></i><span>Copy</span>
              </button>
            </div>
          ` : ''}
          ${secretKeyJson ? `
            <div class="secret-value">
              <span>JSON secret</span>
              <code>${escapeHtml(secretKeyJson)}</code>
              <button class="pill-button" type="button" data-action="copy-wallet-secret" data-secret-type="secretKeyJson">
                <i class="fa-solid fa-copy"></i><span>Copy</span>
              </button>
            </div>
          ` : ''}
          <button class="secondary-button compact" type="button" data-action="hide-wallet-secret">
            <i class="fa-solid fa-eye-slash"></i><span>Hide</span>
          </button>
        </div>
    </div>` : ''}
  ` : '<div class="empty-state">No launch wallet.</div>';

  // Old launch wallets and unfinished launches live in History; here they
  // only get a pointer, and only when there is something to look at.

  $('#assetTable').innerHTML = proofAssets.length ? `
    <div class="wallet-proof-heading">
      <strong>${proofIsDemo ? 'From the test launch (not on-chain)' : 'From the last launch'}</strong>
    </div>
    ${proofAssets.map((item) => `
      <article class="asset-row">
        <span>
          <h3>${escapeHtml(item.name)}</h3>
          <p>${escapeHtml(item.type)} / ${escapeHtml(item.detail)}</p>
        </span>
        <span class="risk-badge ${stateClass(item.state)}">${escapeHtml(item.state)}</span>
        <button class="pill-button" type="button" data-action="inspect-proof-asset" data-proof-kind="${escapeHtml(item.kind)}" ${item.kind === 'report' ? `data-url="${escapeHtml(item.detail)}"` : ''}>Inspect</button>
      </article>
    `).join('')}
  ` : '';
}

// Every key Trebuchet holds, read from the chain: the ones holding anything are listed, and
// Sweep all sends each launch wallet's tokens and SOL to the return wallet, one at a time.
// Read in the background too (every 5 minutes at most), so counts elsewhere come from the chain.
function refreshHeldWallets({ force = false, background = false } = {}) {
  const held = state.heldWallets;
  if ((!background && state.activeView !== 'wallet') || state.apiStatus !== 'connected' || !state.apiClient?.listHeldWallets) return;
  if (held.loading || (!force && held.list && Date.now() - held.at < (background ? 300_000 : 30_000))) return;
  state.heldWallets = { ...held, loading: true, error: null };
  state.apiClient.listHeldWallets()
    .then(async ({ wallets }) => {
      state.heldWallets = { ...state.heldWallets, list: wallets.map((wallet) => ({ ...wallet, contents: null, error: null })), at: Date.now() };
      renderHeldWallets();
      const queue = [...state.heldWallets.list];
      const worker = async () => {
        for (let row = queue.shift(); row; row = queue.shift()) {
          try { row.contents = await walletContents(row.address, { fresh: force }); } catch (error) { row.error = error.message || 'Could not read'; }
          renderHeldWallets();
        }
      };
      // The strip and Recovery count wallets from these reads.
      const settle = () => { if (state.activeView !== 'wallet') renderAll(); };
      await Promise.all([worker(), worker(), worker(), worker()]);
      settle();
    })
    .catch((error) => { state.heldWallets = { ...state.heldWallets, error: error.message || 'Could not list the keys' }; })
    .finally(() => { state.heldWallets = { ...state.heldWallets, loading: false }; renderHeldWallets(); });
}

function heldWalletHoldsAnything(row) {
  return Boolean(row.contents && (row.contents.lamports > 0 || row.contents.tokens.length || row.contents.openAccounts));
}

function sweepAllTargets() {
  return (state.heldWallets.list || [])
    .filter((row) => (row.kind === 'launch' || row.kind === 'retired') && row.readable !== false && walletSweepable(row.contents))
    .map((row) => row.address);
}

function renderHeldWallets() {
  const target = $('#heldWallets');
  if (!target) return;
  const { list, sweep, error } = state.heldWallets;
  if (!list) { target.innerHTML = error ? `<p class="is-error">${escapeHtml(error)}</p>` : ''; return; }
  const read = list.filter((row) => row.contents || row.error).length;
  const holding = list.filter(heldWalletHoldsAnything);
  const targets = sweepAllTargets();
  const running = sweep && !sweep.finished;
  const locked = state.secretPin.locked;
  const button = running
    ? `<button class="primary-button compact" type="button" disabled><span class="rail-spin" aria-hidden="true"></span><span>Sweeping ${sweep.done + 1} of ${sweep.total}</span></button>`
    : locked && targets.length
      ? '<button class="primary-button compact" type="button" data-action="unlock-secret-pin"><i class="fa-solid fa-lock-open"></i><span>Unlock PIN to sweep</span></button>'
      : `<button class="primary-button compact" type="button" data-action="sweep-all-wallets" ${targets.length ? '' : 'disabled'}><i class="fa-solid fa-broom"></i><span>Sweep all${targets.length ? ` (${targets.length})` : ''}</span></button>`;
  const status = (row) => {
    if (sweep?.current === row.address) return '<span class="risk-badge">Sweeping</span>';
    const failure = sweep?.failed.find((item) => item.address === row.address);
    if (failure) return `<span class="risk-badge danger" title="${escapeHtml(failure.error)}">Not swept</span>`;
    return '';
  };
  target.innerHTML = `
    <div class="held-wallets-head">
      <span><strong>Keys in Trebuchet</strong><small>${list.length} keys · ${read < list.length ? `${read} read · ` : ''}${holding.length} holding anything</small></span>
      <span class="held-wallets-action">${button}${!running && !targets.length && read === list.length ? '<small>Nothing to sweep</small>' : ''}</span>
    </div>
    ${holding.length ? `<ul class="held-wallets-list">${holding.map((row) => `
      <li>${walletChipHtml(row.address, { label: WALLET_KEY_LABELS[row.kind] || '' })}<span>${escapeHtml(walletContentsSummary(row.contents))}</span>${status(row)}</li>`).join('')}</ul>` : ''}
    ${sweep?.finished ? `<p class="held-wallets-result" role="status">Swept ${sweep.total - sweep.failed.length} of ${sweep.total}${sweep.failed.length ? `; ${sweep.failed.length} not swept` : ''}.</p>` : ''}`;
}

async function sweepAllWallets() {
  const targets = sweepAllTargets();
  if (!targets.length || state.heldWallets.sweep?.finished === false) return;
  if (state.fullRunRunning || state.realExecutionRunning) return;
  const defaultDestination = state.destinations?.signed?.[0] || state.destinations?.funder || '';
  const confirmation = await openSweepConfirmation({ publicKey: `${targets.length} launch wallet${targets.length === 1 ? '' : 's'}`, defaultDestination });
  if (!confirmation) return;
  const sweep = { total: targets.length, done: 0, current: null, failed: [], finished: false };
  state.heldWallets = { ...state.heldWallets, sweep };
  for (const address of targets) {
    sweep.current = address;
    renderHeldWallets();
    try {
      await state.apiClient.sweepPendingWallet({ walletPublicKey: address, destinationWallet: confirmation.destinationWallet });
    } catch (error) {
      sweep.failed.push({ address, error: error.message || 'Sweep failed' });
    }
    const row = (state.heldWallets.list || []).find((item) => item.address === address);
    if (row) row.contents = await walletContents(address, { fresh: true }).catch(() => row.contents);
    sweep.done += 1;
  }
  sweep.current = null;
  sweep.finished = true;
  renderHeldWallets();
  refreshLocalApiState().catch(() => null);
}

function personalTokenName(token) {
  return token?.symbol || token?.name || shortAddress(token?.mint);
}

function personalTokenDetail(token, type, knownByMint) {
  if (type === 'known') {
    const walletCount = Number(token.walletCount) || 0;
    return `${walletCount} wallet${walletCount === 1 ? '' : 's'} · ${formatDiscoveryPrice(token.priceUsd)}`;
  }
  const holderCount = Number(token.holderCount) || 0;
  const seedCount = Number(token.seedCount) || 0;
  return `${holderCount} holder${holderCount === 1 ? '' : 's'} · ${seedCount} connection${seedCount === 1 ? '' : 's'}`;
}

function personalTokenCards(tokens, type, knownByMint) {
  return tokens.map((rawToken) => {
    const token = discoveryDisplayToken(rawToken);
    const label = personalTokenName(token);
    const brandStatus = token.brand?.classification || null;
    return `
      <button class="personal-token-card" type="button" data-action="inspect-personal-token" data-token="${escapeHtml(token.mint)}" ${discoveryPaletteAttributes(token)}>
        ${discoveryTokenMark(token, 'personal-token-mark')}
        <span class="personal-token-copy">
          <strong>${escapeHtml(label)} ${token.name && token.name !== token.symbol ? `<span class="muted">${escapeHtml(token.name)}</span>` : ''}</strong>
          <small>${escapeHtml(personalTokenDetail(token, type, knownByMint))}</small>
        </span>
        ${type === 'candidate'
          ? `<span class="network-score ${brandStatus ? discoveryStatusClass(brandStatus) : ''}" title="${escapeHtml(brandStatus ? `${brandStatus} · ` : '')}Relevance ${Math.max(0, Math.min(100, Number(token.networkScore) || 0))}/100"><strong>${Math.max(0, Math.min(100, Number(token.networkScore) || 0))}</strong></span>`
          : '<span class="network-score is-known" title="Held by a tracked wallet"><i class="fa-solid fa-wallet"></i></span>'}
      </button>
    `;
  }).join('');
}

function discoveryWalletChip(wallet) {
  return `
    <span class="discovery-wallet-chip ${wallet.enabled === false ? 'is-paused' : ''}" title="${escapeHtml(wallet.publicKey)}">
      <i class="fa-solid ${wallet.source === 'managed' ? 'fa-key' : 'fa-eye'}"></i>
      <strong>${escapeHtml(wallet.label || shortAddress(wallet.publicKey))}</strong>
      <span>${escapeHtml(fullAddress(wallet.publicKey))}</span>
      <button type="button" data-action="toggle-discovery-wallet" data-wallet="${escapeHtml(wallet.publicKey)}" data-enabled="${wallet.enabled === false ? 'true' : 'false'}" aria-label="${wallet.enabled === false ? 'Resume' : 'Pause'} ${escapeHtml(wallet.label || 'wallet')}" ${state.discovery.walletBusy || state.discovery.scanning ? 'disabled' : ''}>
        <i class="fa-solid ${wallet.enabled === false ? 'fa-play' : 'fa-pause'}"></i>
      </button>
      ${wallet.source === 'watch-only' ? `
        <button type="button" data-action="remove-discovery-wallet" data-wallet="${escapeHtml(wallet.publicKey)}" aria-label="Remove ${escapeHtml(wallet.label || 'wallet')}" ${state.discovery.walletBusy || state.discovery.scanning ? 'disabled' : ''}>
          <i class="fa-solid fa-xmark"></i>
        </button>
      ` : ''}
    </span>
  `;
}

function renderPersonalDiscovery() {
  const connected = state.apiStatus === 'connected';
  const wallets = state.discovery.wallets || [];
  const watchOnlyWallets = wallets.filter((wallet) => wallet.source !== 'managed');
  const managedWallets = wallets.filter((wallet) => wallet.source === 'managed');
  const scanConcurrency = Number(state.discovery.limits?.scanConcurrency) || 4;
  const enabledWatchOnlyCount = watchOnlyWallets.filter((wallet) => wallet.enabled !== false).length;
  const enabledManagedCount = managedWallets.filter((wallet) => wallet.enabled !== false).length;
  const walletRenderLimit = Math.max(100, Number(state.discovery.walletRenderLimit) || 100);
  const visibleWatchOnlyWallets = watchOnlyWallets.slice(-walletRenderLimit).reverse();
  const visibleManagedWallets = managedWallets.slice(0, walletRenderLimit);
  const snapshot = state.discovery.snapshot;
  const knownTokens = Array.isArray(snapshot?.knownTokens) ? snapshot.knownTokens : [];
  const candidates = Array.isArray(snapshot?.candidates) ? snapshot.candidates : [];
  const knownByMint = new Map(knownTokens.map((token) => [token.mint, token]));
  const scanButton = $('#personalDiscoveryScanButton');
  const addButton = $('#discoveryWalletAddButton');
  const sortInput = $('#personalDiscoverySort');
  if (sortInput && sortInput.value !== state.discovery.sort) sortInput.value = state.discovery.sort;
  if (scanButton) {
    scanButton.disabled = !connected
      || state.discovery.scanning
      || enabledWatchOnlyCount + enabledManagedCount === 0;
    scanButton.innerHTML = state.discovery.scanning
      ? '<i class="fa-solid fa-spinner fa-spin"></i><span>Scanning</span>'
      : '<i class="fa-solid fa-rotate"></i><span>Refresh</span>';
  }
  if (addButton) {
    addButton.disabled = !connected || state.discovery.walletBusy || state.discovery.scanning;
    addButton.title = '';
  }
  ['discoveryWalletInput', 'discoveryWalletLabelInput'].forEach((id) => {
    if ($(`#${id}`)) $(`#${id}`).disabled = !connected || state.discovery.walletBusy || state.discovery.scanning;
  });

  $('#discoveryWallets').innerHTML = `
    <section class="discovery-wallet-group">
      <header>
        <span><i class="fa-solid fa-eye"></i> Watched wallets</span>
        <small>${watchOnlyWallets.length}</small>
      </header>
      <div class="discovery-wallet-chip-list">
        ${watchOnlyWallets.length
          ? visibleWatchOnlyWallets.map(discoveryWalletChip).join('')
          : '<span class="muted">Add addresses you want Trebuchet to follow.</span>'}
      </div>
      ${watchOnlyWallets.length > visibleWatchOnlyWallets.length ? `
        <button class="pill-button discovery-wallet-show-more" type="button" data-action="show-more-discovery-wallets">
          Show ${Math.min(100, watchOnlyWallets.length - visibleWatchOnlyWallets.length)} more watched wallets
        </button>
      ` : ''}
    </section>
    ${managedWallets.length ? `
      <section class="managed-discovery-wallets">
        <header class="managed-head">
          <span><i class="fa-solid fa-key"></i> ${managedWallets.length} launch wallet${managedWallets.length === 1 ? '' : 's'}</span>
          <small>Automatic</small>
        </header>
        <div class="discovery-wallet-chip-list">${visibleManagedWallets.map(discoveryWalletChip).join('')}</div>
        ${managedWallets.length > visibleManagedWallets.length ? `
          <button class="pill-button discovery-wallet-show-more" type="button" data-action="show-more-discovery-wallets">
            Show ${Math.min(100, managedWallets.length - visibleManagedWallets.length)} more launch wallets
          </button>
        ` : ''}
      </section>
    ` : ''}
    ${enabledWatchOnlyCount + enabledManagedCount ? `<p class="discovery-scan-budget">Refresh looks through ${enabledWatchOnlyCount + enabledManagedCount} wallet${enabledWatchOnlyCount + enabledManagedCount === 1 ? '' : 's'}, ${scanConcurrency} at a time.</p>` : ''}
  `;

  const progressLabel = personalDiscoveryProgressLabel();
  const rawScanWarnings = Array.isArray(snapshot?.warnings) ? snapshot.warnings : [];
  const legacyBoundedScan = rawScanWarnings.some((warning) => /Scanned \d+ of \d+ enabled wallets/i.test(String(warning)));
  const scanWarnings = [
    ...(legacyBoundedScan ? ['Previous result used the retired bounded scanner. Scan again to include every enabled wallet.'] : []),
    ...rawScanWarnings.filter((warning) => !/Scanned \d+ of \d+ enabled wallets/i.test(String(warning))),
  ];
  const tokenCount = knownTokens.length + candidates.length;
  if ($('#personalDiscoveryTokenCount')) $('#personalDiscoveryTokenCount').textContent = `${tokenCount}`;
  const scanSummary = snapshot
    ? `${candidates.length} network · ${knownTokens.length} held · ${formatAge(snapshot.completedAt)}`
    : null;
  const status = state.discovery.personalError
    || progressLabel
    || (snapshot
      ? scanSummary
      : enabledWatchOnlyCount + enabledManagedCount > 0
        ? ''
        : 'Add a wallet first.');
  const progress = state.discovery.job?.progress || {};
  const progressTotal = Math.max(0, Number(progress.total) || 0);
  const progressCurrent = Math.max(0, Math.min(progressTotal, Number(progress.current) || 0));
  const progressPercent = progressTotal > 0 ? Math.round((progressCurrent / progressTotal) * 100) : 0;
  ['personalDiscoveryStatus', 'discoveryWalletStatus'].forEach((id) => {
    const statusNode = $(`#${id}`);
    if (!statusNode) return;
    // The Wallets tab already says to add an address; don't say it twice.
    if (id === 'discoveryWalletStatus' && !snapshot && !state.discovery.personalError && !state.discovery.scanning
      && enabledWatchOnlyCount + enabledManagedCount === 0) {
      statusNode.innerHTML = '';
      return;
    }
    statusNode.classList.toggle('is-error', Boolean(state.discovery.personalError));
    statusNode.classList.toggle('is-warning', !state.discovery.personalError && scanWarnings.length > 0);
    statusNode.title = scanWarnings.join('\n');
    statusNode.innerHTML = `
      <span><i class="fa-solid ${state.discovery.personalError || scanWarnings.length ? 'fa-triangle-exclamation' : state.discovery.scanning ? 'fa-spinner fa-spin' : 'fa-shield-halved'}"></i> ${escapeHtml(status)}</span>
      ${state.discovery.scanning && progressTotal > 0 ? `<span class="discovery-progress-meter" role="progressbar" aria-valuemin="0" aria-valuemax="${progressTotal}" aria-valuenow="${progressCurrent}"><i style="width:${progressPercent}%"></i></span>` : ''}
    `;
  });

  if (!snapshot) {
    if ($('#personalDiscoveryTokenCount')) $('#personalDiscoveryTokenCount').textContent = '0';
    $('#personalTokenNetwork').innerHTML = '<div class="discovery-feed-empty">No tokens yet.</div>';
    return;
  }
  const feed = [
    ...candidates.map((token) => ({ token, type: 'candidate' })),
    ...knownTokens.map((token) => ({ token, type: 'known' })),
  ];
  const sortedFeed = [...feed].sort((left, right) => {
    if (state.discovery.sort === 'name') {
      return String(personalTokenName(left.token)).localeCompare(String(personalTokenName(right.token)));
    }
    if (state.discovery.sort === 'connections') {
      const leftConnections = left.type === 'known' ? Number(left.token.walletCount) || 0 : Number(left.token.holderCount) || 0;
      const rightConnections = right.type === 'known' ? Number(right.token.walletCount) || 0 : Number(right.token.holderCount) || 0;
      return rightConnections - leftConnections
        || (Number(right.token.networkScore) || 0) - (Number(left.token.networkScore) || 0);
    }
    const leftRelevance = left.type === 'known' ? 101 : Number(left.token.networkScore) || 0;
    const rightRelevance = right.type === 'known' ? 101 : Number(right.token.networkScore) || 0;
    return rightRelevance - leftRelevance
      || (Number(right.token.holderCount) || 0) - (Number(left.token.holderCount) || 0);
  });
  $('#personalTokenNetwork').innerHTML = `
    <div class="personal-token-feed" role="list" aria-label="Discovered tokens">
      ${sortedFeed.length
        ? sortedFeed.map(({ token, type }) => personalTokenCards([token], type, knownByMint)).join('')
        : '<span class="discovery-feed-empty">No tokens found.</span>'}
    </div>
  `;
}

const DISCOVERY_PANES = ['tokens', 'wallets', 'inspect', 'saved'];

function renderDiscoveryPanes() {
  const pane = DISCOVERY_PANES.includes(state.discovery.activePane) ? state.discovery.activePane : 'tokens';
  state.discovery.activePane = pane;
  $$('.discovery-pane-tab').forEach((button) => {
    const selected = button.dataset.discoveryPane === pane;
    button.classList.toggle('is-selected', selected);
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex = selected ? 0 : -1;
  });
  $$('[data-discovery-pane-panel]').forEach((panel) => {
    const selected = String(panel.dataset.discoveryPanePanel).split(/\s+/).includes(pane);
    panel.hidden = !selected;
    panel.classList.toggle('is-active', selected);
  });
  $('.discovery-grid')?.classList.toggle('is-wallet-tracking', pane === 'wallets');
}

function renderDiscovery() {
  const selected = selectedDiscovery();
  const rows = filteredDiscoveryRecords();
  const connected = state.apiStatus === 'connected';
  const queryInput = $('#discoverySearchInput');
  const mintInput = $('#discoveryMintInput');
  const inspectButton = $('#discoveryInspectButton');

  renderPersonalDiscovery();
  renderDiscoveryPanes();

  const shield = state.discovery.brandShield;
  const shieldAlerts = Number(shield?.alertCount || 0);
  const shieldCritical = Number(shield?.criticalAlertCount || 0);
  const watcherCandidates = Number(shield?.watcherCandidateCount || 0);
  $('#discoverySourceBanner').innerHTML = `
    <span class="risk-badge ${!connected ? 'warn' : shieldCritical ? 'danger' : ''}">${!connected ? 'Offline' : shieldCritical ? `${shieldCritical} critical` : 'Brand Shield'}</span>
    <span>${connected
      ? `${Number(shield?.officialLaunchCount || 0)} verified · ${shieldAlerts} alerts · ${watcherCandidates} signals`
      : 'Local API unavailable.'}</span>
  `;

  if (queryInput && queryInput.value !== state.discovery.query) queryInput.value = state.discovery.query;
  if (mintInput && state.discovery.lastInspectedMint && !mintInput.value) mintInput.value = state.discovery.lastInspectedMint;
  if (inspectButton) {
    inspectButton.disabled = state.discovery.inspecting || !connected;
    inspectButton.innerHTML = state.discovery.inspecting
      ? '<i class="fa-solid fa-spinner fa-spin"></i><span>Analyzing</span>'
      : '<i class="fa-solid fa-magnifying-glass-chart"></i><span>Analyze token</span>';
  }
  $('#discoveryRegistryCount').textContent = `${state.discovery.records.length}`;
  document.querySelectorAll('[data-discovery-filter]').forEach((button) => {
    button.classList.toggle('is-active', button.dataset.discoveryFilter === state.discovery.filter);
  });
  $('#discoveryError').innerHTML = state.discovery.error
    ? `<span><i class="fa-solid fa-triangle-exclamation"></i> ${escapeHtml(state.discovery.error)}</span>`
    : '';

  $('#discoveryTable').innerHTML = rows.length ? rows.map((token) => {
    const change24h = token.market?.priceChange?.h24 ?? token.metrics?.change24h;
    const liquidityUsd = token.market?.liquidityUsd ?? token.metrics?.liquidityUsd;
    const volume24hUsd = token.market?.volume24hUsd ?? token.metrics?.volume24hUsd;
    const provenance = discoveryLocalProvenance(token);
    return `
      <button class="discovery-row ${token.id === state.selectedDiscoveryId ? 'is-active' : ''}" type="button" data-action="select-discovery" data-token="${escapeHtml(token.id)}" ${discoveryPaletteAttributes(token)}>
        ${discoveryTokenMark(token)}
        <span class="discovery-copy">
          <h3>${escapeHtml(token.name)} <span class="muted">${escapeHtml(token.symbol)}</span></h3>
          <span class="market-line">
            <strong>${formatDiscoveryPrice(token.priceUsd)}</strong>
            <span class="${discoveryTrendClass(change24h)}">${formatDiscoveryPercent(change24h, '24h —')}</span>
            <span>${formatDiscoveryUsd(liquidityUsd)} pool value</span>
            <span>${formatDiscoveryUsd(volume24hUsd)} volume</span>
            ${provenance.proof || provenance.journal ? '<span class="has-provenance" title="Local launch proof">✓</span>' : ''}
          </span>
        </span>
        <span class="score-block">
          <strong>${token.score}</strong>
          <span class="meter"><span style="width:${token.score}%"></span></span>
        </span>
        <span class="source-block">
          <span class="risk-badge ${discoveryStatusClass(token.status)}">${escapeHtml(token.status)}</span>
          <span>${formatAge(token.inspectedAt)}</span>
        </span>
      </button>
    `;
  }).join('') : `
    <div class="discovery-empty">
      <i class="fa-solid fa-satellite-dish"></i>
      <strong>${state.discovery.records.length ? 'No matches' : 'No saved analysis'}</strong>
      <span>${state.discovery.records.length
        ? 'Change the filter.'
        : 'Inspect a mint above.'}</span>
    </div>
  `;

  if (!selected) {
    const snapshot = state.discovery.snapshot;
    const knownCount = Array.isArray(snapshot?.knownTokens) ? snapshot.knownTokens.length : 0;
    const networkCount = Array.isArray(snapshot?.candidates) ? snapshot.candidates.length : 0;
    const watchedCount = (state.discovery.wallets || []).filter((wallet) => wallet.source !== 'managed').length;
    const managedCount = (state.discovery.wallets || []).filter((wallet) => wallet.source === 'managed').length;
    const trackedCount = watchedCount + managedCount;
    $('#evidencePanel').innerHTML = `
      <div class="discovery-detail-empty">
        <i class="fa-solid fa-compass"></i>
        <strong>Select a token</strong>
        <span>${knownCount + networkCount
          ? `${knownCount + networkCount} in the feed.`
          : trackedCount
            ? `Refresh ${trackedCount} wallet${trackedCount === 1 ? '' : 's'}.`
            : 'Add a wallet first.'}</span>
        <div class="discovery-overview-stats">
          <span><small>Held</small><strong>${knownCount}</strong></span>
          <span><small>Network</small><strong>${networkCount}</strong></span>
          <span><small>Tracked wallets</small><strong>${trackedCount}</strong></span>
        </div>
        <button class="primary-button compact" type="button" data-action="${trackedCount ? 'scan-personal-discovery' : 'open-wallet-tracking'}">${trackedCount ? 'Refresh' : 'Add wallet'}</button>
      </div>
    `;
    hydrateDiscoveryTokenPalettes();
    return;
  }

  const provenance = discoveryLocalProvenance(selected);
  const evidence = Array.isArray(selected.evidence)
    ? selected.evidence.filter((item) => !['Trebuchet provenance', 'Market price'].includes(item.label))
    : [];
  const market = selected.market || null;
  const marketPrice = market?.priceUsd ?? selected.priceUsd;
  const change24h = market?.priceChange?.h24 ?? selected.metrics?.change24h;
  const change7d = market?.history?.changePercent;
  const marketTrend = change7d ?? change24h;
  const supply = selected.metrics?.supply
    ? compactAmount(Number(selected.metrics.supply))
    : '—';
  const topTenValue = selected.metrics?.topTenPercent == null
    ? '—'
    : `${Number(selected.metrics.topTenPercent).toFixed(2)}%`;
  const transactions = market?.transactions24h || {};
  const buys = Number(transactions.buys);
  const sells = Number(transactions.sells);
  const tradeCount = (Number.isFinite(buys) ? buys : 0) + (Number.isFinite(sells) ? sells : 0);
  const marketChart = discoveryPriceChart(market);
  const inspectionSource = String(selected.source || 'Configured RPC')
    .replace(/\s*\+\s*local Trebuchet journals$/i, '');
  const warningSummaries = (selected.warnings || []).map(discoveryWarningSummary);
  const brand = selected.brand || null;
  const brandDetail = brand?.evidence?.[0]?.detail
    || (brand?.official
      ? brand.provenanceVerified ? 'Signed Trebuchet launch provenance verified.' : 'Registered in this Trebuchet installation.'
      : 'No matching signed Trebuchet launch provenance was found.');
  const brandRiskClass = ['critical', 'high'].includes(String(brand?.risk || '').toLowerCase())
    ? 'danger'
    : String(brand?.risk || '').toLowerCase() === 'medium'
      ? 'warn'
      : discoveryStatusClass(brand?.classification);
  const localEvidence = [
    provenance.journal ? `
      <div class="audit-line">
        <span class="evidence-dot pass"></span>
        <span><strong>Launch journal</strong><small>${escapeHtml(provenance.journal.status || 'recorded')} · ${formatDate(provenance.journal.updatedAt)}</small></span>
      </div>
    ` : '',
    provenance.proof ? `
      <div class="audit-line">
        <span class="evidence-dot pass"></span>
        <span><strong>Trebuchet proof bundle</strong><small>Matching local proof loaded</small></span>
      </div>
    ` : '',
  ].filter(Boolean).join('');

  $('#evidencePanel').innerHTML = `
    <div class="evidence-head" ${discoveryPaletteAttributes(selected)}>
      ${discoveryTokenMark(selected)}
      <span class="evidence-identity">
        <h3>${escapeHtml(selected.name)} <span>${escapeHtml(selected.symbol)}</span></h3>
        <span class="evidence-identity-meta">
          <code title="${escapeHtml(selected.mint)}">${escapeHtml(fullAddress(selected.mint))}</code>
          ${brand ? `<span class="risk-badge ${brandRiskClass}" title="${escapeHtml(brandDetail)}"><i class="fa-solid ${brand.official ? 'fa-shield-halved' : 'fa-shield'}"></i>${escapeHtml(brand.classification)}</span>` : ''}
        </span>
      </span>
      <span class="evidence-price">
        <strong>${formatDiscoveryPrice(marketPrice)}</strong>
        <small class="${discoveryTrendClass(change24h)}">${formatDiscoveryPercent(change24h, '24h —')}</small>
      </span>
    </div>
    <section class="market-card" aria-label="Token market history">
      <div class="market-card-head">
        <span><small>${market ? 'GeckoTerminal' : 'Price'}</small><strong>7 days</strong></span>
        <span class="${discoveryTrendClass(marketTrend)}">${formatDiscoveryPercent(change7d)}</span>
      </div>
      ${marketChart || `
        <div class="market-chart-empty">
          <i class="fa-solid fa-chart-area"></i>
          <span><strong>No market history</strong></span>
        </div>
      `}
      ${marketChart ? `
        <div class="market-chart-range">
          <span><small>Low</small><strong>${formatDiscoveryPrice(market?.history?.lowUsd)}</strong></span>
          <span><small>Updated</small><strong>${formatAge(market?.history?.asOf)}</strong></span>
          <span><small>High</small><strong>${formatDiscoveryPrice(market?.history?.highUsd)}</strong></span>
        </div>
      ` : ''}
    </section>
    <div class="market-stats">
      <span><small>Pool inventory value</small><strong>${formatDiscoveryUsd(market?.liquidityUsd)}</strong></span>
      <span><small>Volume</small><strong>${formatDiscoveryUsd(market?.volume24hUsd)}</strong></span>
      <span><small>${market?.marketCapUsd != null ? 'Market cap' : 'FDV'}</small><strong>${formatDiscoveryUsd(market?.marketCapUsd ?? market?.fdvUsd)}</strong></span>
      <span><small>Trades</small><strong>${tradeCount || '—'}</strong></span>
    </div>
    ${window.TrebuchetMarketEvidence?.reserves(market?.reserves) || ''}
    
    <p class="pool-support-intro">Volume: ${formatDiscoveryUsd(market?.volume6hUsd)} over 6 hours · ${formatDiscoveryUsd(market?.volume24hUsd)} over 24 hours.</p>
    <button class="secondary-button compact" type="button" data-action="open-market-evidence" data-mint="${escapeHtml(selected.mint)}">Pool locks, fee owners and sell quotes</button>
    <div class="detail-section-label">
      <span>Chain</span>
      <small>${selected.score} · ${escapeHtml(selected.status)}</small>
    </div>
    <div class="evidence-summary-strip">
      <span><small>Supply</small><strong>${escapeHtml(supply)}</strong></span>
      <span><small>Top 10</small><strong>${escapeHtml(topTenValue)}</strong></span>
    </div>
    <div class="evidence-facts">
      ${evidence.map((item) => `
        <div class="evidence-fact">
          <span>${escapeHtml(item.label)}</span>
          <strong><span class="evidence-dot ${escapeHtml(item.state || 'unknown')}"></span>${escapeHtml(item.value)}</strong>
        </div>
      `).join('')}
    </div>
    <div class="evidence-mint-line">
      <small>Mint</small>
      <code title="${escapeHtml(selected.mint)}">${escapeHtml(selected.mint)}</code>
    </div>
    <div class="discovery-actions">
      <button class="secondary-button compact" type="button" data-action="refresh-discovery" data-token="${escapeHtml(selected.mint)}" ${state.discovery.inspecting ? 'disabled' : ''}>
        <i class="fa-solid fa-rotate"></i><span>Refresh</span>
      </button>
      <button class="secondary-button compact" type="button" data-action="copy-discovery-mint" data-token="${escapeHtml(selected.mint)}">
        <i class="fa-solid fa-copy"></i><span>Copy</span>
      </button>
    </div>
    <section class="discovery-more">
      <header class="more-head"><span>Details</span>${warningSummaries.length ? `<small>${warningSummaries.length} warning${warningSummaries.length === 1 ? '' : 's'}</small>` : ''}</header>
      <div class="discovery-audit">
      <div class="audit-line">
        <span class="evidence-dot pass"></span>
        <span><strong>${escapeHtml(inspectionSource)}</strong><small>Inspected ${formatAge(selected.inspectedAt)}</small></span>
      </div>
      ${localEvidence || `
        <div class="audit-line muted">
          <i class="fa-solid fa-link-slash"></i>
          <span><strong>RPC only</strong><small>No local launch artifacts linked</small></span>
        </div>
      `}
      ${warningSummaries.map((warning) => `
        <div class="discovery-warning-line">
          <div class="warning-head">
            <i class="fa-solid fa-triangle-exclamation"></i>
            <span><strong>${escapeHtml(warning.title)}</strong><small>${escapeHtml(warning.detail)}</small></span>
          </div>
          <code title="${escapeHtml(warning.raw)}">${escapeHtml(warning.raw)}</code>
        </div>
      `).join('')}
      <div class="discovery-notes">
        <div class="notes-head"><span>Notes</span><small>${selected.notes ? 'Saved' : 'Add'}</small></div>
        <label class="discovery-notes-editor">
          <textarea id="discoveryNotesInput" rows="2" maxlength="500" placeholder="Questions or verification context…">${escapeHtml(selected.notes || '')}</textarea>
        </label>
      </div>
      <button class="secondary-button compact danger-button" type="button" data-action="remove-discovery" data-token="${escapeHtml(selected.mint)}">
        <i class="fa-solid fa-trash"></i><span>Remove saved analysis</span>
      </button>
      </div>
    </section>
  `;
  hydrateDiscoveryTokenPalettes();
}

function approvalTransaction() {
  if (state.activeApprovalId) {
    const tx = state.transactions.find((item) => item.id === state.activeApprovalId);
    if (tx) return tx;
  }
  return state.transactions.find((tx) => tx.state === 'pending') || null;
}

function approvalHtml() {
  const current = account();
  const tx = approvalTransaction();
  const selectedLock = selectedManagedWallet() ? walletLockInfo(selectedManagedWallet()) : { state: null };
  const keyGone = selectedLock.state === 'missing' || selectedLock.state === 'wrong-key';
  const lockedWord = keyGone ? selectedLock.label : 'Locked';
  // The Recovery PIN opens every saved key, so it can be unlocked even when the selected wallet's own key is gone.
  const pinLocked = state.secretPin.configured && state.secretPin.locked && !state.secretPin.damaged;
  if (!tx) {
    return `
      <div class="approval-head">
        <span>
          <span class="eyebrow">Launch wallet</span>
          <h2>${walletIsUnlocked() ? 'Unlocked' : escapeHtml(lockedWord)}</h2>
        </span>
        <span class="badge">${escapeHtml(authoritativeNetworkLabel())}</span>
      </div>
      <div class="approval-body">
        <div class="kv-row"><span>Wallet</span><strong>${walletIsUnlocked() ? escapeHtml(current.name) : escapeHtml(lockedWord)}</strong></div>
        <p>${keyGone ? escapeHtml(selectedLock.detail) : 'Nothing to approve yet. Set up the token, then fund the launch wallet.'}${keyGone && pinLocked ? ' The Recovery PIN is also locked: unlock it to use your other saved keys.' : ''}</p>
      </div>
      <div class="approval-actions">
        <button class="secondary-button" type="button" data-action="close-approval">Close</button>
        ${pinLocked
          ? '<button class="primary-button" type="button" data-action="unlock-secret-pin">Unlock PIN</button>'
          : `<button class="primary-button" type="button" data-action="toggle-wallet" ${keyGone ? 'disabled' : ''}>${walletIsUnlocked() ? 'Lock' : 'Unlock'}</button>`}
      </div>
    `;
  }
  const rows = signatureRows();
  const pendingRows = rows.filter((item) => item.state === 'pending');
  const config = currentLaunchConfig();
  const recoveryEndpoint = recoveryAuthorizationEndpoint();
  const recoverySpec = {
    '/api/finish-token-creation': {
      eyebrow: 'One saved step',
      title: 'Finish token',
      detail: 'Complete only the missing token work.',
    },
    '/api/resume-launch': {
      eyebrow: 'One saved step',
      title: 'Finish liquidity',
      detail: 'Reuse the recorded pools and finish only what is missing.',
    },
    '/api/reveal-sealed-metadata': {
      eyebrow: 'One saved step',
      title: 'Reveal identity',
      detail: 'Publish the name, symbol and logo, then lock them for good.',
    },
    '/api/transfer-assets': {
      eyebrow: 'Final saved step',
      title: 'Finish launch',
      detail: 'Save the launch record, then send everything to the return wallet.',
    },
  }[recoveryEndpoint] || null;
  const fundingStatus = classicFundingEstimateStatus(config);
  const currentEstimate = window.TrebuchetV2RuntimeState?.fundingEstimate({
    estimateMatches: fundingStatus.matchesConfig,
    estimatedSol: state.classicFundingEstimate?.totalSol,
  }) || { available: false, value: null, label: 'Estimate required' };
  const finishingInterruptedToken = state.executionReadiness?.nextEndpoint === '/api/finish-token-creation';
  const armingTokenCreation = ['/api/create-token', '/api/finish-token-creation'].includes(state.executionReadiness?.nextEndpoint);
  const primaryLabel = recoverySpec && !walletIsUnlocked() ? 'Unlock PIN &amp; approve' : 'Approve';

  return `
    <div class="approval-head">
      <span>
        ${recoverySpec?.eyebrow ? `<span class="eyebrow">${escapeHtml(recoverySpec.eyebrow)}</span>` : ''}
        <h2>${recoverySpec ? escapeHtml(recoverySpec.title) : armingTokenCreation ? `Review before ${finishingInterruptedToken ? 'finishing' : 'creating'} ${escapeHtml(state.launchPlan?.token?.symbol || $('#tokenSymbol').value || 'the token')}` : `Review the ${escapeHtml(state.launchPlan?.token?.symbol || $('#tokenSymbol').value || 'token')} launch`}</h2>
      </span>
    </div>
    <div class="approval-body">
      <div class="kv-row"><span>Wallet</span><strong>${escapeHtml(current.name)}</strong></div>
      <div class="kv-row"><span>Network</span><strong>${escapeHtml(authoritativeNetworkLabel())}</strong></div>
      ${recoverySpec
        ? `<div class="kv-row approval-pin-row"><span>PIN</span><strong>${walletIsUnlocked() ? 'Ready' : 'Unlock required'}</strong></div>`
        : `<div class="kv-row"><span>Estimate</span><strong>${currentEstimate.available ? fmtSol(currentEstimate.value) : 'Required'}</strong></div>`}
      <p class="approval-scope-note"><i class="fa-solid fa-shield-halved"></i> ${recoverySpec?.detail ? `${escapeHtml(recoverySpec.detail)} ` : ''} Approving sends nothing.</p>
      ${!recoverySpec ? pendingRows.slice(0, 2).map((item) => `<p><i class="fa-solid fa-check"></i> ${escapeHtml(item.label)}</p>`).join('') : ''}
      ${!recoverySpec && pendingRows.length > 2 ? `<p><i class="fa-solid fa-ellipsis"></i> ${pendingRows.length - 2} more</p>` : ''}
    </div>
    <div class="approval-actions">
      <button class="secondary-button" type="button" data-action="close-approval">Cancel</button>
      <button class="primary-button" type="button" data-action="run-launch">${primaryLabel}</button>
    </div>
  `;
}

function renderExtension() {
  const html = approvalHtml();
  const approvalInline = document.getElementById('approvalInline');
  const approvalFloating = $('#approvalFloating');

  if (approvalInline) approvalInline.innerHTML = html;
  if (approvalFloating) {
    approvalFloating.innerHTML = html;
    approvalFloating.classList.toggle('is-recovery', Boolean(recoveryAuthorizationEndpoint()));
    approvalFloating.classList.toggle('needs-pin', !walletIsUnlocked());
    approvalFloating.classList.toggle('is-open', state.approvalOpen && state.activeView === 'launch');
  }

}

